window.POEM_CONTENT = {
  "poems/tale-of-wandering-poet.html": {
    "title": "Tale of the Wandering Poet",
    "subtitle": "A meditation on versions and transformation",
    "form": "Free Verse",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>Which version is it?</p>\n          <p>I can't seem to find you in my poetry anymore.</p>\n          <p>Is it you or someone else?</p>\n          <p>In the years that I knew you,</p>\n          <p>now more years went past loving you.</p>\n          <p>Can I count it on my hand,</p>\n          <p>or the pages of poetry</p>\n          <p>that have you as a \"her\"</p>\n          <p>who just slips past as thoughts</p>\n          <p>from my heart through my fingers</p>\n          <p>into my diary's fading ink?</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>Now, with your mention in its stead,</p>\n          <p>the page seems complete yet haunted</p>\n          <p>of the old memories that I let go.</p>\n          <p>But it does come back,</p>\n          <p>coming through the faint cracks</p>\n          <p>that slowly close as time passes by.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>Which version are you now,</p>\n          <p>that has bled into my heart today?</p>\n          <p>Which version are you tomorrow,</p>\n          <p>that sleeps silently as I prattle</p>\n          <p>about my life that is without worries?</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>Which version would you be</p>\n          <p>when I love someone again?</p>\n          <p>I am confident that this love,</p>\n          <p>that I used to feel for you,</p>\n          <p>will only make me feel even stronger</p>\n          <p>for the destined woman</p>\n          <p>that I have been waiting</p>\n          <p>for the past few lifetimes.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>Which version would you be, my destiny?</p>\n          <p>I await your soft advent into my heart</p>\n          <p>to win it without contention.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>Which version am I?</p>\n          <p>Living as a wandering poet,</p>\n          <p>believing, as I walk away from yesterday.</p>\n        </div>"
  },
  "poems/hairpin.html": {
    "title": "The Hairpin",
    "subtitle": "Written for the ones who go to war",
    "form": "Free Verse",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>It's a lonely Saturday, I watch the jet planes fly into oblivion</p>\n          <p>Lying on my roof, I spectate as a memory burns away</p>\n          <p>With the cigarette, that burned beside me wailing as it lay.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>First view of the city is always different in the morning</p>\n          <p>I see it, the boy cries a little less as he gets flimsy</p>\n          <p>And the windows, of the old building seem a little less dusty.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>Shelter from the storm, I was given when I passed her way</p>\n          <p>It was another lifetime, when everything was new and bold</p>\n          <p>A transient memory, which is now old.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>Not a word was spoken, the first time I met her gaze</p>\n          <p>The rain showered, heavily upon us on this old alleyway</p>\n          <p>I could hear piano strings, in my heart playing away.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>I hoped, that I won't fall in love with her</p>\n          <p>Since love, never fails to make me blue</p>\n          <p>And as the whistle blows, I boarded the train that was always due.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>I bid her farewell, and as a tear fell from her cheek</p>\n          <p>The train started, moving in a motion swift</p>\n          <p>While I did not confess, these feelings that I had wrapped in a gift.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>It was a hairpin, that she once was mesmerised by</p>\n          <p>Now it remains, with me forever hidden</p>\n          <p>As I had gone to war, for people to be ridden.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>When I came back, with an artificial eye</p>\n          <p>Which only sees the past, a time with her</p>\n          <p>And the other, sees a hairpin and jet planes since December.</p>\n        </div>"
  },
  "poems/in-the-rain.html": {
    "title": "In the Rain",
    "subtitle": "For a friend lost to the rain.",
    "form": "Free Verse",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>This rain that pours me with sorrow and grief</p>\n          <p>also took away my world's only relief.</p>\n          <p>My friend, who smiled brightly even when the nights felt shallow,</p>\n          <p>left his loved ones and this world which had made him hollow.</p>\n          <p>So many days have slipped by</p>\n          <p>but this agony doesn't pass by.</p>\n          <p>This distress often returns in my life,</p>\n          <p>like the rain which doesn't know when to confide.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>In just two years, we had found a brother in each other,</p>\n          <p>but we never found closure for the crosses we had borne for the other.</p>\n          <p>While I never realised how greatly I would regret</p>\n          <p>for not helping you when you were in need,</p>\n          <p>I went on with my life with this anguish in my heart which never deceased.</p>\n          <p>I walk with regret on this life's slope,</p>\n          <p>and I stroll on this lonely road which has fell silent</p>\n          <p>without your voice filled with hope.</p>\n          <p>They remind me of all those memories that now seem bittersweet,</p>\n          <p>of us having a laugh about how life had its fair share of sour and sweet.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>Now as I move on with my life, I carry a sheet filled with poems,</p>\n          <p>about a friend whom I lost amidst the rain filled with regrets and sorrows.</p>\n          <p>So as I move on in life and write these poems</p>\n          <p>under the roof of an old soul who looks to pay his amend,</p>\n          <p>thus I could only hope</p>\n          <p>that you would think about me every now and then,</p>\n          <p>old friend.</p>\n        </div>"
  },
  "poems/september.html": {
    "title": "September",
    "subtitle": "A month that never intends to stay.",
    "form": "Free Verse",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>She was a woman of my dreams</p>\n          <p>who was like the ending of summer</p>\n          <p>and now I have wasted years</p>\n          <p>in pursuit of forgetting her.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>A woman who appeared in a storm</p>\n          <p>came and instilled a calmness</p>\n          <p>that I couldn't have asked as my norm</p>\n          <p>yet, it's all I could ask in a tone, reckless.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>She was a woman who brought spring</p>\n          <p>into my rain and sorrow filled life</p>\n          <p>but she disappeared in the wind</p>\n          <p>just when my love had come alive.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>She was a woman whose smile</p>\n          <p>had become my heart's desire</p>\n          <p>and as I dreamt her on an aisle</p>\n          <p>she faded and made my life a satire.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>She seldom made me question</p>\n          <p>my sentimental approach to destiny</p>\n          <p>now all I do is smile in tandem</p>\n          <p>with the poems I write in mockery.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>Her hands so warm and kind</p>\n          <p>played the piano in the key of C</p>\n          <p>that brought solace to my mind</p>\n          <p>while I wrote a haiku that got lost in sea.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>She brought a change in me for good</p>\n          <p>while I wanted to be close to her</p>\n          <p>yet I could never get the chance</p>\n          <p>as she always had him beside her.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>Perhaps she's the only reason</p>\n          <p>why I write this sorrowful poem</p>\n          <p>however, loving her maybe my treason</p>\n          <p>as I have forgotten the song she did hum.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IX</span>\n          <p>Maybe the reason I write this song</p>\n          <p>is a way of avenging my grief</p>\n          <p>but her memory does prolong</p>\n          <p>a sorrow that I have hid in this leaf.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">X</span>\n          <p>Now as I sit on this park bench</p>\n          <p>I reminisce a time of August</p>\n          <p>while the leaves that fall on the trench</p>\n          <p>have turned to brown in downcast.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XI</span>\n          <p>I take a trip down memory lane</p>\n          <p>when I had bid farewell to my love</p>\n          <p>inspite of my mind's constant refrain</p>\n          <p>as my heart had given up on its luck.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XII</span>\n          <p>My heart is trying to rejoin in trust</p>\n          <p>with leaves of spring that were green</p>\n          <p>and now have turned to brown this August</p>\n          <p>while I just get old with poems in between.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XIII</span>\n          <p>As seasons have passed quickly</p>\n          <p>I started questioning my empathy</p>\n          <p>that seems to have flown swiftly</p>\n          <p>in this wind that flows until its rainy.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XIV</span>\n          <p>I have never been in love before</p>\n          <p>is what my paranoid peers often say</p>\n          <p>but my poems act as proof on their own</p>\n          <p>as these people tend to be in dismay.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XV</span>\n          <p>She was the woman I met in September,</p>\n          <p>a month that never intends to stay.</p>\n        </div>"
  },
  "poems/a-ring-in-the-rain.html": {
    "title": "A Ring in the Rain",
    "subtitle": "Love seen through a curtain of rain.",
    "form": "Free Verse",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>While I walk under these lush green trees</p>\n          <p>that were blessed with rain</p>\n          <p>they make me perceive an emotion</p>\n          <p>that resembles my pain.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>Sometimes I feel like crying</p>\n          <p>without any idea or reason</p>\n          <p>even the clouds shower with rain</p>\n          <p>on this world filled with treason.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>As I stroll beside these lonely streams</p>\n          <p>I realised how the world changed</p>\n          <p>while time flows as it seems</p>\n          <p>with clusters of emotions left stranded.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>I sit on the banks of this deserted river</p>\n          <p>I notice how the slight drizzle of the rain</p>\n          <p>and the cold breeze makes me shiver</p>\n          <p>even the muffler she had given hadn't softened the pain.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>I look upon this rain</p>\n          <p>which drenches me in anguish,</p>\n          <p>I wonder if it could for once, fain</p>\n          <p>and I grin, for my nostalgic wish.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>During the ending of one summer</p>\n          <p>I had fallen in love too bold</p>\n          <p>now comes a summer that reminds me of her</p>\n          <p>and of a love which once was new but now has grown old.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>A heartsick smile appeared on my face</p>\n          <p>as I sauntered among the rain in autumn</p>\n          <p>I found a place to sit under this shade</p>\n          <p>a place that I had forgotten</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>I walked up to it where I saw pieces of mozzarella</p>\n          <p>just to find her sitting there</p>\n          <p>with her hands gripping a blue umbrella</p>\n          <p>a serene silence engulfed the lair.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IX</span>\n          <p>I saw the ring on her finger</p>\n          <p>an anguish filled my mind</p>\n          <p>I felt a grief that still seemed to linger</p>\n          <p>while the rain hid my tears in hindsight.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">X</span>\n          <p>Her hair had seemed to have grown longer</p>\n          <p>while she seemed so glad to see me</p>\n          <p>I just smiled and waited for a harbinger</p>\n          <p>who could be the one to hear my plea.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XI</span>\n          <p>I recalled the scars that she once left plentiful</p>\n          <p>she still is the woman whom I can't forget</p>\n          <p>I saw her again and it feels like a curse too beautiful</p>\n          <p>and she comes anchored with a love in regret.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XII</span>\n          <p>I bleed through my fingers</p>\n          <p>that were once gruesomely rough</p>\n          <p>now I walk away from a love that shivers</p>\n          <p>a love that has tortured me long enough.</p>\n        </div>"
  },
  "poems/jessie.html": {
    "title": "Jessie",
    "subtitle": "For the syllables I couldn't think of in a poem.",
    "form": "Free Verse",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>It's been a long time since I last heard you sing. Somedays I just find myself looking at your photograph while my heart just grieves.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>Now you have grown your hair and moved somewhere, a place where I could never come close to. I arrived at that place yet I remained distanced, a shimmering thought stopped me, making me blue.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>You never owed me anything, yet I owe everything I know about love and life, to you.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>You were the syllables I couldn't think of in a poem and you were the melody that lacked in my symphony.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>I visualise you in my poetry, dancing with words in the garden of my heart while I aimlessly await your return to these rain drenched streets that are empty.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>In my mind, you float across my lonely and grieving waters. With just a glimpse of your smile, my mind dispels all my horrors.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>Some seasons ago, I read you in some kind of a poem. I shivered when I wondered how poets had come across love that felt like anguish for me and for them.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>I played my guitar one lonely evening, it wept through a soothing melody that felt blue, a tune that reminded me of how ill fated I was for not being with you.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IX</span>\n          <p>A poem over you often feels undone. Then I wonder why I spend my time, writing poems that I can't believe, writing words that resemble you yet feel ridiculous when they rhyme.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">X</span>\n          <p>If she could read my mind, she could see a tale unfolding itself, a tale that lets me visualise her, standing still under the moonlight in Vermont.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XI</span>\n          <p>When I can not sing my heart, I can only speak my mind. Then I write on these meaningless sheets, filling my heart out and I let the words sing a melody, a melody that has faint reminisces of you.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XII</span>\n          <p>I may forget to write once I get old, I may forget the lies and the truths of my present and past, but the only truth worth remembering, would be you.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XIII</span>\n          <p>Half of what I said is meaningless, but I said it just to reach you. Several seasons have passed and I couldn't reach you, so I write this poem of love for you, Jessie.</p>\n        </div>"
  },
  "poems/does-the-rain-ever-fall.html": {
    "title": "Does the Rain Ever Fall on Us",
    "subtitle": "A conversation under the rain.",
    "form": "Free Verse",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>Does the rain ever fall on us as a sign?</p>\n          <p>She asked me in an apologetic tone</p>\n          <p>I wondered if it was raining in her heart or mine</p>\n          <p>while I stood beside her, blessed by her cologne.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>Does the windy rain make you shiver?</p>\n          <p>I asked her while the breezy wind blew</p>\n          <p>her hair that personified peace like a river</p>\n          <p>while I fell in love with eyes that were blue.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>Does the rain ever fail to embrace?</p>\n          <p>She asked me so nonchalantly</p>\n          <p>while I looked at her with a lonely face</p>\n          <p>and answered the question honestly.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>Rain is my close friend indeed</p>\n          <p>it helps me hide my sorrowful tears</p>\n          <p>and helps me smile without any greed</p>\n          <p>that I had hid in my heart for years.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>I also often seek the early morning rain</p>\n          <p>and its haunting yet merciful pain</p>\n          <p>while I wondered if my heart could ever feign</p>\n          <p>for a grieving tomorrow, that follows me in the rain.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>While the raindrops fell on her heavenly skin</p>\n          <p>I thanked God for this gracious day of July</p>\n          <p>while my fountain pen and I, live a life of sin,</p>\n          <p>as I wrote a small poem on a butterfly.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>A silence engulfed in the air, and I dreaded</p>\n          <p>a haunting verse that came into my head</p>\n          <p>and as rain fell on this crooked shade</p>\n          <p>I wondered if I was actually living or dead.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>Did the rain take us on a journey yet?</p>\n          <p>I thought out loud as my love for her</p>\n          <p>spoke in silence and her hair that was wet</p>\n          <p>felt like a sight that could make me quiver.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IX</span>\n          <p>When the rain untimely stopped</p>\n          <p>we stepped outside, from the shade</p>\n          <p>and the garden that was swamped</p>\n          <p>while I wished that we had stayed.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">X</span>\n          <p>Will we ever happen to meet on this long road?</p>\n          <p>I thought to myself as we bid adieu in charade</p>\n          <p>we went our separate ways, and as I started for my abode</p>\n          <p>I looked back and noticed a smile on her face.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XI</span>\n          <p>A smile so hauntingly beautiful in that outwind</p>\n          <p>made my heart long for her and almost made me pursue</p>\n          <p>those feelings for her, that have now withered in the wind</p>\n          <p>leaving only memories, that I also meant to bid adieu.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XII</span>\n          <p>Does the rainy sky ever fill you with hope?</p>\n          <p>I wondered as several seasons had went by</p>\n          <p>I prayed, that I could meet her once more on this life's slope</p>\n          <p>and to be in love with a girl that could make me sway.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XIII</span>\n          <p>As I walk along this nostalgic garden</p>\n          <p>that had once helped me write a poem</p>\n          <p>now only flowers blossom here that seem golden</p>\n          <p>as the blue sky filled the scenery in tandem.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XIV</span>\n          <p>I stroll under this blue and rainy sky</p>\n          <p>endless thoughts cross my poetic mind</p>\n          <p>I recall the memory of a girl from a July</p>\n          <p>while rain falls on me and my timid hind</p>\n          <p>&nbsp;</p>\n          <p>I wished once more, under this shade</p>\n          <p>to meet her again in this rainy place</p>\n          <p>now I pray one more time, as I delayed</p>\n          <p>the thoughts that longingly chase,</p>\n          <p>&nbsp;</p>\n          <p>for a simple twist of fate.</p>\n        </div>"
  },
  "poems/lost-at-sea.html": {
    "title": "Lost at Sea",
    "subtitle": "The helmsman's grief.",
    "form": "Free Verse",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>Lost at sea,</p>\n          <p>the horizon as the captain's destination</p>\n          <p>a memory in his mind starts to flee</p>\n          <p>reminding him of a time when he was free from his desolation.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>Even with burdens on their shoulders</p>\n          <p>the passengers seem to smile freely</p>\n          <p>yet a misery resides on their fingers</p>\n          <p>while the helmsman steers through the waves cautiously.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>Ponders the yachtsman with a heart that is heavy</p>\n          <p>and a soul that can never be free</p>\n          <p>from all the times he drinks in misery</p>\n          <p>and the times when this heart was his own and once, so was she.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>With an aching in their heart</p>\n          <p>the dockers dance in the early mornin rain</p>\n          <p>the seafarer watches on, near a pillar that is scarred</p>\n          <p>and with eyes that reflect his long lost pain.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>The old salt remembers a place where the liquor tasted good</p>\n          <p>now, in the sea, it tastes of his guilt, anger</p>\n          <p>and a depression that he has withstood</p>\n          <p>while he searches for a rope that feels rougher.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>This old boat gets the bosun down, it makes him suffer</p>\n          <p>as a rush of distasteful memories come to his mind</p>\n          <p>pushing him to his limits and making him tougher</p>\n          <p>all he does is cling on to a hope, a hope that one day he could go see his child.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>The ferryman feels stuck on this boat</p>\n          <p>feeling cold, drunk and lethargic</p>\n          <p>he rows with a might that lets it stay afloat</p>\n          <p>and now only God could bring him hope.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>Somedays a blue mist surrounds the sailor's soul</p>\n          <p>he wonders when his heart would be free</p>\n          <p>from the sorrow that makes him whole</p>\n          <p>and from the apathy that binds his heart from being carefree.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IX</span>\n          <p>At the end of the sea</p>\n          <p>the cap'n stops searching for a purpose or a destination</p>\n          <p>he realises that he can't see</p>\n          <p>the horizon that he once felt was his salvation.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">X</span>\n          <p>The company grasp their life's lonely tale</p>\n          <p>as they come to understand</p>\n          <p>that life is all about the journey in detail</p>\n          <p>rather than its destination, that once had made them leave their homeland.</p>\n        </div>"
  },
  "poems/almost-blue.html": {
    "title": "Almost Blue",
    "subtitle": "A saxophone's confession.",
    "form": "Free Verse",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>I am almost blue</p>\n          <p>and maybe just because of you</p>\n          <p>why does it feel to be true</p>\n          <p>that I won't ever find someone like you.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>A mind as empty as mine</p>\n          <p>feels a remorse that none can subside</p>\n          <p>I think if I move towards her side</p>\n          <p>I may fall in love in a slippery slide.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>Somedays I think she is not for me</p>\n          <p>I fear to be vulnerable as a bee</p>\n          <p>as I worry to be her eyes's abductee</p>\n          <p>and I wonder if her treacherous smile could lead me somewhere,</p>\n          <p>a place where my heart feels free.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>Yet that seems unlikely</p>\n          <p>as my saxophone blares a melody</p>\n          <p>that resonates my broken heart's fallacy</p>\n          <p>and my piano plays perfectly</p>\n          <p>in a key that only brings forth a melancholy.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>Whenever I see you merely sigh</p>\n          <p>I worry for you and for this heart's desire</p>\n          <p>then I feign a wry smile</p>\n          <p>as my heart wonders if it could ever reach you once in a while.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>When I stroll on a rainy night</p>\n          <p>I reminisce an old love that seldom gives my heart a fright</p>\n          <p>I wonder if my silence could ever make a woman mine</p>\n          <p>I realised that my heartache was my only plight.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>This rainy night, a soft rain seems to fall</p>\n          <p>bringing down sorrows that never dawn</p>\n          <p>and as a drip from leaves falls on my shoulder</p>\n          <p>I remembered a thorny rose in the rain,</p>\n          <p>tempting me to be engulfed into its own downfall,</p>\n          <p>a rose that was only for her, once upon a time, in an autumn's fall.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>Yet my heart craves for a love that it could for only once, pursue</p>\n          <p>someone new has bewitched me and flew</p>\n          <p>she is a woman that could fill this heart with something new</p>\n          <p>a woman that had hair and eyes like you</p>\n          <p>and my heart is ready to get away from you.</p>\n          <p>&nbsp;</p>\n          <p>Yet there's a piece of you in how I dress</p>\n          <p>thus my heart is almost blue</p>\n          <p>and it could be only because of you</p>\n          <p>&nbsp;</p>\n          <p>It's always been you.</p>\n        </div>"
  },
  "poems/eyes-almost-blue.html": {
    "title": "Eyes Almost Blue",
    "subtitle": "She carried your eyes in a different face.",
    "form": "Free Verse",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>One rainy evening,</p>\n          <p>I heard an old tune from a street</p>\n          <p>I stood under a shade as heavy rain came down in a heartbeat</p>\n          <p>I lit a cigarette for my pain that almost made my heart weep.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>This rain brings memories wrapped in tears</p>\n          <p>I realised that the poems I write have always been about you,</p>\n          <p>a woman of my past, a memory that nobody shares.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>My eyes closed as I listened to that melody</p>\n          <p>a melody that had reminisces of your melancholy</p>\n          <p>memories that linger in this symphony</p>\n          <p>and cling onto a breeze that resembles my heart's fallacy.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>A vendor smiles and sways to this melody's magic</p>\n          <p>a simple twist of fate had made its tactic</p>\n          <p>as I caught a glimpse of a woman who could prove that love is in itself, tragic</p>\n          <p>the rain was spinning a story that had no logic</p>\n          <p>I realised I may fall in love with her and felt pathetic.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>I caught a glimpse of her eyes that were almost blue</p>\n          <p>my heartbeat stopped for that moment when she looked into my eyes too</p>\n          <p>I became eager to write about her and this scenery as it all felt too good to be true.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>My heart felt light yet heavy</p>\n          <p>I had forgotten this feeling that has retraced back to me as my heart felt a bit rainy</p>\n          <p>I see her drying her wet hair under the same shade, while she wore a smile that could wound any man that seemed dreamy</p>\n          <p>we both looked at the street that has a past memory.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>This woman who stands five feet beside me carries a peculiar reminiscent of you</p>\n          <p>I know that to be absurd yet my heart feels it to be true</p>\n          <p>her blue eyes look my way and I fear it might only be you</p>\n          <p>my eyes look into hers that moment and just as a car passed by us, my eyes flew.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>For the first time, I didn't despise the rain</p>\n          <p>in the past it only showed my unbearable pain</p>\n          <p>fate always felt cruel, twisting my life as it only made tragedy remain</p>\n          <p>but now I stand beside a woman that makes me want to fall in love again.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IX</span>\n          <p>I saw people write about love but I thought it was not meant for me</p>\n          <p>all I have managed to write about is heartbreak as my heart is yet to be free</p>\n          <p>now as I talk with this woman, I hope to make my heart a guarantee</p>\n          <p>a guarantee of a love that could remain within me and without me.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">X</span>\n          <p>We both smiled with glee</p>\n          <p>we looked at the rain drenched streets where people just flee</p>\n          <p>the rain was heavy and our umbrella was as useless as a bee</p>\n          <p>I started falling in love with her and with this place that had made me its abductee.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XI</span>\n          <p>We waited for the rain to become calmer</p>\n          <p>yet I prayed for the rain to be harsher</p>\n          <p>&nbsp;</p>\n          <p>And again we stood waiting</p>\n          <p>for a memory that was yet to be reaching</p>\n          <p>then the melody made me start humming</p>\n          <p>a tune that prompted me of you and your eyes that were always shining</p>\n          <p>I realised that I hadn't forgotten about you although I shouldn't be longing.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XII</span>\n          <p>I stood there, calming my heart</p>\n          <p>I braced myself for another wound</p>\n          <p>as I had decided to find a love for this woman that has made my heart fall apart</p>\n          <p>&nbsp;</p>\n          <p>She is reading an anthology while sharing glances with me in silence</p>\n          <p>my heart beats as fast as I can imagine and runs out of patience</p>\n          <p>as I look at the rain, I call out a poem from the book she was reading in solace.</p>\n          <p>&nbsp;</p>\n          <em>\"A faint clap of thunder</em>\n          <em>clouded skies</em>\n          <em>perhaps rain comes again</em>\n          <em>if so, stay with me?\"</em>\n          <p>&nbsp;</p>\n          <p>She smiles in a calm manner and replies</p>\n          <p>&nbsp;</p>\n          <em>\"A faint clap of thunder</em>\n          <em>even if rain comes not</em>\n          <em>I will stay here together with you</em>\n          <em>and if it rains, I wonder if you would stay here too?\"</em>\n          <p>&nbsp;</p>\n          <p>My mind went blank in joy, then I perceived a reply that I had given to you several seasons ago, to this same verse.</p>\n          <p>But I couldn't say it out loud as it seemed like a curse.</p>\n          <p>Yet I said it in my mind, as it wasn't something I could just subside.</p>\n          <em>\"Even if it doesn't rain, I'll be here,</em>\n          <em>waiting for you or someone like you.\"</em>\n          <p>&nbsp;</p>\n          <p>I stood there, feeling guilty of falling for someone other than you</p>\n          <p>yet she feels almost you</p>\n          <p>I saw your eyes in her that are almost blue</p>\n          <p>yet I still wait for a simple twist of fate that could for once, make it all true.</p>\n        </div>"
  },
  "poems/once-more.html": {
    "title": "Once More",
    "subtitle": "On love that returns to haunt.",
    "form": "Free Verse",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>I had forgotten her voice and face,</p>\n          <p>but now I can see her in the flower in my vase.</p>\n          <p>Now she messages me again,</p>\n          <p>making me reminisce the love I had to refrain.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>The serenity in her voice and eyes,</p>\n          <p>yet again brings me to my knees at sunrise.</p>\n          <p>She showers her signs of sympathy upon me,</p>\n          <p>feels like an utter and unjust misery.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>When my hands had just found peace,</p>\n          <p>she comes again to rattle my sleep.</p>\n          <p>My hands have started wandering again,</p>\n          <p>towards a pen that writes down my pain.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>Now I write down a poem about a tale,</p>\n          <p>that seems to her like a funny charade.</p>\n          <p>Golden slumbers fill her eyes and dry mine,</p>\n          <p>a sorrow that befalls on my words, on this line.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>I was on a hiatus from this suffering,</p>\n          <p>now she returns with a smile that seems to be a good way of covering.</p>\n          <p>But this heart knows that it's a comedy,</p>\n          <p>for my soul knows about her apathy.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>I had met her and that was fate's twist,</p>\n          <p>but now, she comes back with a cynical fit.</p>\n          <p>I write beside a window on a rainy day,</p>\n          <p>and these words strain to rhyme yet, I pray.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>Now I move on with my life as I did before,</p>\n          <p>without any concrete purpose anymore.</p>\n          <p>I must keep on writing poems about her and someone like her,</p>\n          <p>until I find the words to this incomplete poem,</p>\n          <p>that lies ahead on this long and winding road.</p>\n        </div>"
  },
  "poems/eleventh-of-april.html": {
    "title": "11th of April",
    "subtitle": "A date that stays in the blood.",
    "form": "Free Verse",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>I saunter among the autumn</p>\n          <p>leaves that have turned brown</p>\n          <p>while I write a melancholic poem</p>\n          <p>about my life, as I foolishly drown.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>I drown in these nonsensical</p>\n          <p>emotions that do overwhelm</p>\n          <p>me, and my pen which remain fatal</p>\n          <p>on this rainy day, that I condemn.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>I take refuge under a lonely shade</p>\n          <p>and I ponder about the signal</p>\n          <p>that my heart has for the dead</p>\n          <p>feelings that forcefully linger.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>I place my hands onto the wood</p>\n          <p>that has become fragile with time</p>\n          <p>I realised that I never understood</p>\n          <p>how a caterpillar could climb.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>I see raindrops falling on a flower</p>\n          <p>that seeps through the shade</p>\n          <p>leaving no space for any answer</p>\n          <p>about life, that I wanted in charade.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>While I was searching for clarity</p>\n          <p>I stumbled on this rainy and peaceful</p>\n          <p>place that makes me forget reality</p>\n          <p>but I only write a rhyme too painful.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>11th of April, I had gotten a message</p>\n          <p>from her that was hurting in tandem</p>\n          <p>with the thoughts that lay vestige</p>\n          <p>in my mind and in my sorrowful poem.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>Now it's a rainy day of August</p>\n          <p>a month that only makes promises</p>\n          <p>of cold and chilly winds with trust</p>\n          <p>but now it rains on flowers of hibiscus.</p>\n          <p>&nbsp;</p>\n          <p>I hear the ticking of my watch</p>\n          <p>that is damp from the frisky rain</p>\n          <p>and I crave for a rocks on scotch</p>\n          <p>so that I could feel like a swain.</p>\n          <p>&nbsp;</p>\n          <p>I finish this poem that was due</p>\n          <p>and I walk past a moist flower</p>\n          <p>with an umbrella that is blue</p>\n          <p>which she gave me on a September.</p>\n          <p>&nbsp;</p>\n          <p>I put the poem inside the bag</p>\n          <p>and I open the rusty parasol</p>\n          <p>to protect the bag from the rain</p>\n          <p>as it has a poem and a photograph.</p>\n          <p>&nbsp;</p>\n          <p>It's a poem about her</p>\n          <p>and a photograph of us.</p>\n        </div>"
  },
  "poems/simple-twist-of-fate.html": {
    "title": "Simple Twist of Fate",
    "subtitle": "Wild strawberry fields and a missed bus.",
    "form": "Free Verse",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>Half drunk and completely hopeless,</p>\n          <p>I keep chiming on this typewriter</p>\n          <p>while a hummingbird hums melancholy</p>\n          <p>through these lonesome nights.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>The morning rises with a grief I can't name —</p>\n          <p>I only know it started the day I saw her smile</p>\n          <p>and mistook it for a door.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>I missed my bus on a lonesome rainy day.</p>\n          <p>Life changed with a simple twist of fate:</p>\n          <p>she was standing beside the wild strawberry fields</p>\n          <p>under that gloomy shade,</p>\n          <p>and I forgot where I was going.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>I was guilty of daydreaming in her eyes,</p>\n          <p>in the little details of her life,</p>\n          <p>while time slipped through without asking.</p>\n          <p>Now even the clock is unbearable —</p>\n          <p>it only shows how slowly things move</p>\n          <p>when you are waiting for nothing.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>She showed me winter could have colour.</p>\n          <p>She was proof that autumn could break your heart</p>\n          <p>while still being beautiful.</p>\n          <p>&nbsp;</p>\n          <p>I wonder if I'll find her again —</p>\n          <p>near the garden full of lilies,</p>\n          <p>at the old bookstore,</p>\n          <p>or under an umbrella.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>The words still fall on this page,</p>\n          <p>and I keep writing,</p>\n          <p>half drunk,</p>\n          <p>completely hopeless,</p>\n          <p>waiting one more time</p>\n          <p>for a simple twist of fate.</p>\n        </div>"
  },
  "poems/cafe-in-march.html": {
    "title": "The Café in March",
    "subtitle": "What a café window reveals.",
    "form": "Free Verse",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>I cross puddles formed by</p>\n          <p>the drizzle of rain in March</p>\n          <p>which I often foolishly pry</p>\n          <p>on this lane and in my scotch.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>I hear the faint chirping</p>\n          <p>of birds while I saunter</p>\n          <p>by a garden, pondering</p>\n          <p>about feelings that linger.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>Peculiar thoughts chased</p>\n          <p>my mind while I sipped coffee</p>\n          <p>in a café as I remained dazed</p>\n          <p>by a woman who chose to flee,</p>\n          <p>&nbsp;</p>\n          <p>from my heart and my poem</p>\n          <p>that remains wry and incomplete</p>\n          <p>to this day as my pen in tandem</p>\n          <p>has yet to live up to its conceit.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>I see the world ever changing</p>\n          <p>while I stay in this café's shade</p>\n          <p>taking my time and observing</p>\n          <p>how with life, my emotions fade.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>I notice a mother without a ring</p>\n          <p>who has two kids by her side,</p>\n          <p>frantic to share her loneliness</p>\n          <p>but is clueless where to confide.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>I spotted an old man drown</p>\n          <p>in his sorrows and in his drink</p>\n          <p>while his shirt that was brown</p>\n          <p>had seen grief without a blink.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>I caught a glimpse of a woman</p>\n          <p>who has eyes that were blue</p>\n          <p>drank a juice that had lemon</p>\n          <p>and had an umbrella that was blue.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>My teary eyes await the rain</p>\n          <p>as only my rhymes get to know</p>\n          <p>and see me cry in the nights of pain</p>\n          <p>while life just seems to flow.</p>\n          <p>&nbsp;</p>\n          <p>Rain in the midst of March, made</p>\n          <p>me see a scene that has shades</p>\n          <p>and are now etched under this shade</p>\n          <p>as I write about how it all fades.</p>\n        </div>"
  },
  "poems/only-the-garden-roses.html": {
    "title": "Only the Garden Roses Were Listening",
    "subtitle": "A secret kept by the garden.",
    "form": "Free Verse",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>A day of autumn laden with flowers</p>\n          <p>is accompanied by a sorrowful night</p>\n          <p>hampered with scattering tears</p>\n          <p>in echoes of old memories in plight.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>A hopeful afternoon is spent in a bus</p>\n          <p>sightseeing and travelling around the city,</p>\n          <p>while emotions crash on a dubious</p>\n          <p>humming tune that remains blue and weary.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>I sauntered under the autumn sky</p>\n          <p>in search for an October's wish</p>\n          <p>that would reverse a day of July,</p>\n          <p>a day when she left in anguish.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>I strolled empty streets in the evening</p>\n          <p>I looked upon a tree with orange leaves</p>\n          <p>that made me reminisce a wandering</p>\n          <p>woman whose beauty could rival a lily.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>Seasons ago we met without a choice,</p>\n          <p>my voice sounded like the rusting</p>\n          <p>leaves in front of her enigmatic voice,</p>\n          <p>that was calm even when it was raining.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>She told me to not be so mysterious</p>\n          <p>as we dawdled through a garden</p>\n          <p>I wondered if she really knew</p>\n          <p>my love for her, hidden in my heart's den.</p>\n          <p>&nbsp;</p>\n          <p>Only the garden roses were listening</p>\n          <p>she whispered near the garden of lily,</p>\n          <p>I wondered if fate was recurring</p>\n          <p>or hinting me of another misery.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>Seasons felt like days with her</p>\n          <p>but now, without her, it's an eternal</p>\n          <p>autumn of sorrow in October</p>\n          <p>when even a new love is fatal.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>I boarded a nostalgic train back,</p>\n          <p>but these memories come and go</p>\n          <p>in this benign yet regretful month</p>\n          <p>where only bittersweet memories flow.</p>\n        </div>"
  },
  "poems/it-not-as-if.html": {
    "title": "It's Not As If",
    "subtitle": "The confession hidden in denial",
    "form": "Anaphoric Verse",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>It's not as if I wandered my office to get a glimpse of you,</p>\n          <p>Walking the hallway while nervously fixing my watch.</p>\n          <p>It's not as if I anxiously waited to talk to you,</p>\n          <p>Plotting ways to somehow see you again.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>It's not as if I saw you in the books I read,</p>\n          <p>Or in the garden with the pretty sunflowers that resemble your smile.</p>\n          <p>It's not as if I bought you that gift you liked,</p>\n          <p>After consulting everyone who knew me.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>It's not as if something burned inside me,</p>\n          <p>When I saw you leaving the town.</p>\n          <p>It's not as if I lie to everyone,</p>\n          <p>When I say that I don't dream about you anymore.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>It's not as if you've made yourself a home in my heart,</p>\n          <p>Or in my poem that mentions your blessed eyes.</p>\n          <p>I can't help but admit that this ballad is real,</p>\n          <p>As real as my heart that beats faster at your mention.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>Now an autumn reaches my doorstep</p>\n          <p>As my heart shifts from blue to autumn's orange</p>\n          <p>I remain hopeful for the next day.</p>\n        </div>"
  },
  "poems/regret.html": {
    "title": "Regret",
    "subtitle": "The things I should have known.",
    "form": "Anaphoric Verse",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>If I had known he wouldn't laugh with me again,</p>\n          <p>I'd have held him once more — before the rain.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>If I hadn't taken him for granted,</p>\n          <p>I might have heard the quiet he hid from everyone.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>If I had understood that her kindness wasn't love,</p>\n          <p>I wouldn't have fallen so far into it.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>If I had known this regret would arrive,</p>\n          <p>I'd have spoken. Just once, out loud.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>If my mind hadn't turned against me first,</p>\n          <p>I might have forgiven the losses before they settled.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>If I had seen what her eyes were asking,</p>\n          <p>she wouldn't be something I still write around.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>Long ago, I chose to feel everything too deeply.</p>\n          <p>I've seen, since then, things this mind can't unlearn.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>If I had known there was always a boat to solitude,</p>\n          <p>I would have gone quietly</p>\n          <p>instead of fighting every current home.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IX</span>\n          <p>If I had known that betrayal was just</p>\n          <p>the shape a life takes —</p>\n          <p>I would have found a gentler way to let this one go.</p>\n        </div>"
  },
  "poems/once-again.html": {
    "title": "Once Again",
    "subtitle": "The cyclical nature of longing.",
    "form": "Anaphoric Verse",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>Once again,</p>\n          <p>the regrets keep burdening my shoulder</p>\n          <p>while the melodies which once offered me joy</p>\n          <p>now remind me of a pain that tries to linger</p>\n          <p>and of a sorrow that this pen does enjoy.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>One more time,</p>\n          <p>I wanted myself to stay</p>\n          <p>but my mind advised constraint</p>\n          <p>as my tears no longer lay</p>\n          <p>in wait for her, while my eyes can only refrain.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>How can I erase these,</p>\n          <p>memories that only bring tears</p>\n          <p>of sorrow and benign</p>\n          <p>and will continue for years</p>\n          <p>unless I heal this broken heart of mine.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>One last time,</p>\n          <p>I want to see her somewhere</p>\n          <p>at the same old coffee house that still is plain</p>\n          <p>in a bookstore, reading the sonnets of yesteryear</p>\n          <p>or in a shade, staying away from rain.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>And in those moments,</p>\n          <p>will I be able to find closure?</p>\n          <p>over this love that is deemed to be hopeless</p>\n          <p>will my words of love reach her?</p>\n          <p>that fill my poems, yet, feel wordless.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>Once again,</p>\n          <p>my conscience threatens to be horrified</p>\n          <p>as it seems that these words might fall short</p>\n          <p>before reaching her, while I abide</p>\n          <p>to a twist of fate, that will retort.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>I wait for the day,</p>\n          <p>when this mind may numb this pain</p>\n          <p>that comes and goes in pieces that stray</p>\n          <p>as only the memories remain</p>\n          <p>while I hope that the sorrow slowly fades away.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>These poems stare at me for hours,</p>\n          <p>I write these poems for her</p>\n          <p>or for a woman that seems to be her</p>\n          <p>to read these poems, is all I want from her</p>\n          <p>while I wait for a reply from her.</p>\n          <p>&nbsp;</p>\n          <p>Once again I wait,</p>\n          <p>for a woman to walk into this room</p>\n          <p>in my heart that has long been closed</p>\n          <p>and I smoke a cigarette in wait, that doesn't seem to be a boon</p>\n          <p>while the dying embers of this cigarette that has dozed</p>\n          <p>and of my love,</p>\n          <p>&nbsp;</p>\n          <p>fall on this poem.</p>\n        </div>"
  },
  "poems/my-dear-melancholy.html": {
    "title": "My Dear Melancholy",
    "subtitle": "A dialogue with sorrow itself",
    "form": "Lyric Ode",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>O my dear melancholy</p>\n          <p>You just took her face</p>\n          <p>Caressing the green grass</p>\n          <p>You have arrived so late.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>The old letters make me ponder</p>\n          <p>If the pen writes through its own will</p>\n          <p>Slipping emotions through a finger</p>\n          <p>Putting me in a saddening bliss.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>In a quiet tide of ignorance</p>\n          <p>A past joy that was fleeting</p>\n          <p>Now weighs down heavily</p>\n          <p>On my cigarette that keeps breaking.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>I shadow the joy that seeps</p>\n          <p>Through the merry day</p>\n          <p>Wanting to touch me heaps</p>\n          <p>But, you, never let it find a way.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>You quietly dissect every feud</p>\n          <p>Carving your way with glee</p>\n          <p>And I never end up finding what I need</p>\n          <p>But you find your way to me.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>O my dear melancholy</p>\n          <p>How much have I missed you?</p>\n          <p>O my dear melancholy</p>\n          <p>When will I forsake you?</p>\n        </div>"
  },
  "poems/the-longer-route.html": {
    "title": "The Longer Route",
    "subtitle": "A walk through memory, identity, and the self we carry home",
    "form": "Lyric Meditation",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>I take a longer route as I walk</p>\n          <p>Past the street that I had forgotten</p>\n          <p>Laden with flowers it awaits</p>\n          <p>My treacherous mind's silence.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>Unspoken words seldom spill out</p>\n          <p>As tears that trickle down slow</p>\n          <p>Weighing a life's worth of sorrow</p>\n          <p>That will guide me astray tomorrow</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>Smiling my way through old memories</p>\n          <p>That were left in upon my almira</p>\n          <p>It is a wonder that the delusion</p>\n          <p>Kept itself going without confusion.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>Is it a memory or a longing —</p>\n          <p>The grassland, the sunflowers, and the blue sky</p>\n          <p>A child running through yellow light</p>\n          <p>Or a life I haven't lived into</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>The mind plays its film without asking</p>\n          <p>My eyes well up and they look away</p>\n          <p>While I close the almira, call it nothing</p>\n          <p>Only to weep without warning one day</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>I wore the face that I led myself into</p>\n          <p>And somewhere lost the one beneath</p>\n          <p>My poetry bleeds at every turn now</p>\n          <p>For the self that got lost in time</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>Will she too see only what I've shown</p>\n          <p>And love a face who I've long outgrown</p>\n          <p>Or will she find what I haven't yet</p>\n          <p>A self I cannot remember or own</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>Gradually, I remember the tears</p>\n          <p>The heart that withered at a friend's death</p>\n          <p>Lifetime worth of non validated memories</p>\n          <p>What is true and what is false anymore.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IX</span>\n          <p>Various melodies arrive in a tongue I knew,</p>\n          <p>A Spiritual tune, another with my mother's voice</p>\n          <p>Another which reminisced in a love that left,</p>\n          <p>Or a tune for a love not yet born</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">X</span>\n          <p>It carried an immense longing I cannot place in time</p>\n          <p>Perhaps carried from a life before this</p>\n          <p>I do not know if I need to be held</p>\n          <p>Or if my arms are meant to hold instead</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XI</span>\n          <p>I am now tired of finding answers</p>\n          <p>Loneliness is not the cause of this state</p>\n          <p>When the heart does not have refuge</p>\n          <p>As the call for help was never a smile.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XII</span>\n          <p>Seasons change with every turn</p>\n          <p>Of my poetry and its passages</p>\n          <p>As I look at the serene sunset with wonder</p>\n          <p>Of when it will all dawn on my heart, again.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XIII</span>\n          <p>I take a longer route as I drive</p>\n          <p>Through the lush green nature</p>\n          <p>Where the fresh air makes me bribe</p>\n          <p>My wounded soul, guiding itself into solace.</p>\n        </div>"
  },
  "poems/gazing-at-flowers.html": {
    "title": "Gazing at Flowers",
    "subtitle": "Life goes on within you and without you.",
    "form": "Prose Poem",
    "lang": "en",
    "html": "<div class=\"stanza prose-poem\">\n          <p>We were gazing at the flowers as we wryly smiled through the darkness in our hearts, searching desperately for the light that could guide us through our paths.</p>\n          <p>Birds fly away from the melancholy of my life as I hide my grief and the tears behind this mask I wear on my face.</p>\n          <p>The peaceful birds which had become accustomed to the silence inside of me, now are desperate to rejoice in the thrill which I have long lost.</p>\n          <p>The pain in my heart which was like a nonchalant voice, now becomes a solace for this old soul's void.</p>\n          <p>Everything which was of importance in my life, now feels mundane as I plunge out of the depths of my longing sorrows, yet I fall shortly after, into another depthless void of grief and bittersweet hollows.</p>\n          <p>I often feel as if we all are travellers, looking for a purpose or solitude amidst the inclemencies in our life's purposes. The love that we all possess, guide us through this vast ocean of emotions, acting like a passage, steering us through our agitations.</p>\n          <p>This solitude which we seek, is rather diminishing as we hide the emotions which make us look weak. With time, we come to terms with the magic we all have. All the love, peace and calm that we seek is already in us, we don't need to search for it as the great passage of words and emotions guide us to our own heart and we realise that, life goes on within you and without you.</p>\n        </div>"
  },
  "poems/a-wandering-taxi.html": {
    "title": "A Wandering Taxi",
    "subtitle": "The city at midnight.",
    "form": "Prose Poem",
    "lang": "en",
    "html": "<div class=\"stanza prose-poem\">\n          <p>A wandering taxi stopped in the corner of my street, I sat inside and told him to drive till dawn. His dejected face and his eyes made me realise that we both were wanderers that were just waiting for their moment to drown.</p>\n          <span class=\"taxi-refrain\">Dawdles, the midnight.</span>\n          <p>Lonely streets vanish in the wind as the taxi moves, leaving us with lonely faces, lonely hearts and some remorseful memories. While the taxi swerves through the city, tears fall down my face as I reminisce a time when my heart had an empty room, before she barged in and filled it with a wound deep enough.</p>\n          <span class=\"taxi-refrain\">Lingers on, this wound.</span>\n          <p>I fell in love with her the day I met her, it felt tragic as I couldn't keep my eyes off her. I saw her in class, seated beside a guy, holding hands with him while my pen fell in disbelief as I could see my fate recur.</p>\n          <span class=\"taxi-refrain\">Dawdles on, your memory.</span>\n          <p>Questioning the cruelty of my fate, I spent my days in absolute misery. How could it be that one day life is bliss and the next day, a regretful mockery.</p>\n          <span class=\"taxi-refrain\">Laughs, my fate.</span>\n          <p>Being her friend somedays felt joyful but often it was a saddening anecdote which on every recollection, became darker. My heart desired to stay beside her even if it didn't mount to anything yet it was a torture to be someone of no significance to her.</p>\n          <span class=\"taxi-refrain\">Dithers on, my desire.</span>\n          <p>My heart thought of her as someone that it could have but never keep. It felt like a sin, to have feelings for her when it wouldn't reach her even if it had taken a faithful leap.</p>\n          <span class=\"taxi-refrain\">Loiters on, my sin.</span>\n          <p>When this heart had realised the truth, life swept through in a blur. She is about to be married today and this heart can just hum a saddening melody to soothe my soul until one day, the sun shines brighter.</p>\n          <span class=\"taxi-refrain\">I cling onto, my heart's lie.</span>\n          <p>The taxi stops at the same place I boarded it from. Faint sunshine seeps through my coat and this cold as I walk to the coffee shop where I first saw those brown eyes and fell for them.</p>\n          <span class=\"taxi-refrain\">Linger on, your pale brown eyes.</span>\n        </div>"
  },
  "poems/at-the-turn-of-a-hill.html": {
    "title": "At the Turn of a Hill",
    "subtitle": "A chance encounter",
    "form": "Narrative Verse",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>The flower shop at the turn of a hill</p>\n          <p>Keeps all the pretty flowers at one place</p>\n          <p>While the cold wind in a shrill</p>\n          <p>Flips the pages of my book that is with me for grace</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>Her hair flows like the sea</p>\n          <p>Displaying each curve of her wavy form</p>\n          <p>I wonder if it really is autumn by this tree</p>\n          <p>As her presence seems like a spring's affair</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>The clouds that were darkening over me</p>\n          <p>Were banished by the winds of her stride</p>\n          <p>I was mesmerised by her eyes that fled</p>\n          <p>From mine that looked at her with delight</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>Flowers of jasmine danced at the tune of her emotions</p>\n          <p>I could notice she had an epiphany</p>\n          <p>As her hands were flipping a book's pages</p>\n          <p>And I couldn't help but smile at her symphony</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>A hint of blush on her cheeks</p>\n          <p>As our eyes meet at the romance shelf</p>\n          <p>I pick a novel which reminisces a past love</p>\n          <p>Wondering if there is a future on this hill as I dwell</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>On the hope that shall rescue me from this shrill</p>\n          <p>Hinting me towards a new beginning</p>\n          <p>Guiding me through the end of this misery</p>\n          <p>I was reborn when I saw her at the turn of a hill</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>It was enough for me to concede</p>\n          <p>And saunter ahead with a blank slate</p>\n          <p>While I share this coffee with her that is sweet</p>\n          <p>Making me hopeful for a turn of fate.</p>\n        </div>"
  },
  "poems/girl-with-cat-named-whiskey.html": {
    "title": "The Girl with a Cat Named Whiskey",
    "subtitle": "Sugarless coffee and fading warmth",
    "form": "Narrative Verse",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>This cold evening makes me reminisce</p>\n          <p>A time with her cat and her wry smile</p>\n          <p>Filling my hands with warmth and bliss</p>\n          <p>And memories of old now fade.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>My book of poetry drenched in blue</p>\n          <p>Remains a melancholy that hinders</p>\n          <p>My wait for a love that has been due</p>\n          <p>For countless lonely winters.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>On a cold December night she had caught my attention</p>\n          <p>When flowers were nowhere to be seen</p>\n          <p>Now a spring arrives without her mention</p>\n          <p>And flowers in the garden seem routine.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>The cat drew me towards her in mystery</p>\n          <p>I was not fond of cats which were furry</p>\n          <p>And especially not one named whiskey</p>\n          <p>But the heart yearned change in a hurry.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>I recall sitting in her patio listening to her with sugarless coffee</p>\n          <p>Prattling about life while whiskey would sit on my jacket</p>\n          <p>Listening to our conversations as a hobby</p>\n          <p>And we would kiss, which had become a habit.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>Nowadays I make my coffee with less sugar</p>\n          <p>I drink it with a cigarette in my hand</p>\n          <p>While I try to put a name on this feeling</p>\n          <p>That blew away with the wind as planned.</p>\n        </div>"
  },
  "poems/tokyo.html": {
    "title": "Tokyo",
    "subtitle": "Two strangers in a city that has no gleeful clue",
    "form": "Narrative Verse",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>The red light shines brighter than usual</p>\n          <p>Suggesting a momentary stop.</p>\n          <p>The man looks for clues in the new city</p>\n          <p>An unknown place for poets to rot.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>Everything seems unsure and unheard</p>\n          <p>Most of his time is lost in translation.</p>\n          <p>He saunters through the streets</p>\n          <p>To find a bookstore, secluded from all the fabrication.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>He picks up a dusty novel that was light</p>\n          <p>As his old fashioned pack of cigarettes.</p>\n          <p>Reading a few pages of the old book</p>\n          <p>Reminds him of the thoughts that he cannot digest.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>Sitting in the bar, surrounded by dim lights</p>\n          <p>He sips his whiskey and catches a glimpse or two,</p>\n          <p>Of a woman who wore herself a dress</p>\n          <p>Whose eyes read everything in the room and were blue.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>They somehow light up their cigarettes</p>\n          <p>And prattle about how they are lost</p>\n          <p>In this city which has no gleeful clue</p>\n          <p>About their sorrowful life, in short.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>They roam the night in the streets of Tokyo</p>\n          <p>Finding moments of solace in clamour.</p>\n          <p>She dances like there's no tomorrow</p>\n          <p>And he just observes her undisputed glamour.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>Now they lay on the insomniac bed</p>\n          <p>Talking about all the uncertainty</p>\n          <p>That looms over their confused heads</p>\n          <p>While time passes quickly which before felt like eternity.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>They sleep soundly after days</p>\n          <p>With all the emotions washing away.</p>\n          <p>He wakes up finding her gone</p>\n          <p>A sudden rush of loneliness comes his way.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IX</span>\n          <p>He finds an earring on his night stand</p>\n          <p>Accompanied by a letter he reads,</p>\n          <p>Smiling wryly he packs his bags</p>\n          <p>And for the airport he calmly leaves.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">X</span>\n          <p>He sees the same novel again</p>\n          <p>In someone's arms as he drives the car,</p>\n          <p>He smokes his cigarette sighing bemusedly</p>\n          <p>While the red light turns green from afar.</p>\n        </div>"
  },
  "poems/the-woman-who-brought-spring.html": {
    "title": "The Woman Who Brought Spring",
    "subtitle": "She returned the season.",
    "form": "Narrative Verse",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>I wandered in a garden full of marigold</p>\n          <p>It reminded me of a time that has flown</p>\n          <p>When romantic poetry was for the old</p>\n          <p>And for the people who were left alone.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>I saw a sage like alyssum flower</p>\n          <p>Hiding in beauty among others,</p>\n          <p>It resembled a girl I met in October</p>\n          <p>When leaves fall like feathers.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>These flowers that are not cherished</p>\n          <p>Wither and die like the autumn leaves</p>\n          <p>Which are colored in a lonely dismay</p>\n          <p>Waiting to turn callous and grey.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>My wish to watch the crooked rain</p>\n          <p>Again with her by my side felt a fantasy.</p>\n          <p>And when droplets slid down this shade</p>\n          <p>I saw her again in all her beauty.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>She entered this shade by the flowers</p>\n          <p>And the birds sang the tale of her beauty</p>\n          <p>In a nostalgic &amp; melancholic symphony</p>\n          <p>Which pierced the lines in my poetry.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>She was a woman who I knew once</p>\n          <p>Her smile could even make a rose shy</p>\n          <p>A smile that made me fall in love</p>\n          <p>A love which was new but now is old.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>The rain falling on this shade felt serene</p>\n          <p>But her nostalgic smile like the flowers</p>\n          <p>Seemed more calmer than the rain</p>\n          <p>Which fatefully made us meet again.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>Greetings were exchanged, like the day</p>\n          <p>We met in this garden seasons ago,</p>\n          <p>Now she smiles with a few wrinkles</p>\n          <p>And my words still stumble to flow.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IX</span>\n          <p>I saw her kids stroll along the garden</p>\n          <p>A bittersweet sight for a rainy day</p>\n          <p>A wry smile appeared on the curtain</p>\n          <p>Of my heart that reflected on my face.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">X</span>\n          <p>She bid farewell as the rain subsided</p>\n          <p>Her kids walked under an umbrella</p>\n          <p>Which a long time ago, I had gifted,</p>\n          <p>And I was left longing for the rain again.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XI</span>\n          <p>I sighed as a snowy winter had arrived</p>\n          <p>The chilly winds entered this shade</p>\n          <p>Bringing forth emotions this December</p>\n          <p>That put an end to the reminiscence of her.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XII</span>\n          <p>A beautiful reminiscence that once</p>\n          <p>Was present in my heart for a lifetime</p>\n          <p>Now is left aside while I wander again</p>\n          <p>Without a purpose, writing down</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XIII</span>\n          <p>Poetry that does not have her in it,</p>\n          <p>And a mystery that eludes me</p>\n          <p>Seeps into my mind as I look down</p>\n          <p>To the snow swept streets</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XIV</span>\n          <p>Realising, that life in all its misery</p>\n          <p>Just goes on.</p>\n        </div>"
  },
  "poems/the-wardens-garden.html": {
    "title": "The Warden's Garden",
    "subtitle": "He kept the garden. The garden kept him.",
    "form": "Narrative Verse",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>A man with a horrific past</p>\n          <p>Had done unspeakable deeds</p>\n          <p>Now longs to find peace &amp; be free</p>\n          <p>From those shackles of his creeds.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>He finds a work to escape from calamity</p>\n          <p>A place he could find the peace he craved</p>\n          <p>A place where people were like his family</p>\n          <p>A garden where his life felt paved.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>Spending his days by watering the garden</p>\n          <p>He thinks of himself as a lonely convict</p>\n          <p>And acts as a peaceful warden</p>\n          <p>While he smokes away his mind's verdict.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>He meets a woman in that place</p>\n          <p>She was a maid, who carried a vase</p>\n          <p>And had a peculiar scar on her face</p>\n          <p>That reminded him of cruelty in solace.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>He gives sage advice to people around</p>\n          <p>Which he wished he had got in the past</p>\n          <p>While she stands in the corner of the room</p>\n          <p>With a smile that made him aghast.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>He sits beside her on a rainy evening</p>\n          <p>As she knits him a glove for the winter</p>\n          <p>He looks at her eyes like the moon</p>\n          <p>And fears that he may fall in love with her.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>A notice came from the army one evening</p>\n          <p>She opens the letter and gets tears</p>\n          <p>He finds out that he had been drafted</p>\n          <p>For the rest of his years.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>He had bought her a beautiful hair clip</p>\n          <p>Which he wanted to give her in repose</p>\n          <p>But now, he hides it in his room with a slip</p>\n          <p>Along with the feelings that he cannot disclose.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IX</span>\n          <p>A wistful smile appears on his face</p>\n          <p>As he looks at what he leaves behind,</p>\n          <p>A room full of memories, a charming vase,</p>\n          <p>And people who were family to him.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">X</span>\n          <p>He heads to the station with only a bag full of memories</p>\n          <p>While the household cries in agony.</p>\n          <p>She grabs ahold of him just as he boards</p>\n          <p>Tears fall from her eyes in misery.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XI</span>\n          <p>He wipes her tears, he asks her to marry</p>\n          <p>A nice man &amp; wishes a good life to her.</p>\n          <p>No words of love were said in a hurry</p>\n          <p>As the eyes had already confessed, on one rainy September.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XII</span>\n          <p>With a wry smile, he bids them farewell</p>\n          <p>The train departs, leaving only love</p>\n          <p>And solitude behind as fate could compel</p>\n          <p>He looks at her photo &amp; could only dwell.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XIII</span>\n          <p>He died in war, that was theirs to lose</p>\n          <p>And people left behind could just grieve</p>\n          <p>While a sorrow with an endless premise</p>\n          <p>Had landed on their heart's retrieve.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XIV</span>\n          <p>She is now a Nana &amp; has lived a happy life.</p>\n          <p>Now on her deathbed, she has only one regret,</p>\n          <p>She couldn't convey her feelings that night</p>\n          <p>To an old love that she could never forget.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XV</span>\n          <p>She lost a love in this life's trip</p>\n          <p>While he just vanished in the wind</p>\n          <p>Leaving only that hair clip</p>\n          <p>And those lingering feelings behind,</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XVI</span>\n          <p>In that dusty room from ages ago</p>\n          <p>And the leaves that were green turn to brown.</p>\n        </div>"
  },
  "poems/the-tattered-page.html": {
    "title": "The Tattered Page",
    "subtitle": "Written near a lake's shore, the night before the front.",
    "form": "Narrative Verse",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>A soldier writes on a tattered page,</p>\n          <p>A poem written near a lake's shore</p>\n          <p>That is outside the tents of shade,</p>\n          <p>As of tomorrow, he heads for war.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>It's a lonely &amp; desperate cry for help</p>\n          <p>Under the starry filled night sky</p>\n          <p>He writes this poem on the things he felt</p>\n          <p>About the incidents he perceived in July</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>On duty, so he may not forget reality.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>He saw a fright in the eyes of a recruit</p>\n          <p>Rushing towards the sole bunker</p>\n          <p>Where resides a major who is a hoot,</p>\n          <p>A man who will follow death in a flutter.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>Hearts that had forgotten to slow down</p>\n          <p>Kept running in a dire &amp; constant horror</p>\n          <p>As a bomb on the battlefield may drop down,</p>\n          <p>Adding more bodies to become fodder.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>He saw a bunch of pilots meeting</p>\n          <p>Their families, the smiles were cut in</p>\n          <p>With tears of sorrow that were falling,</p>\n          <p>As of tomorrow, they are airborne therein.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>He heard the story of the lieutenant</p>\n          <p>Who was in enemy land without a dorm,</p>\n          <p>A woman who lived near as a tenant</p>\n          <p>Gave him a shelter from the storm.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>The woman had silver bracelets</p>\n          <p>In her wrists &amp; flowers in her hair</p>\n          <p>She died in his arms, as bullets fired in sets,</p>\n          <p>Now he has no heart for his own share.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IX</span>\n          <p>He observes a deputy who had erupted</p>\n          <p>In anger at the sepoys who were afraid</p>\n          <p>Of the corpses which fate had decided,</p>\n          <p>And God had made flowers in facade.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">X</span>\n          <p>The soldier gets up the next day</p>\n          <p>He arms himself to feel a bit secure</p>\n          <p>While the army doesn't intend to delay,</p>\n          <p>As they join the frontlines to endure.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XI</span>\n          <p>All of them were given a deadly boot</p>\n          <p>As everyone was killed in a dogfight.</p>\n          <p>He was wounded &amp; wanted to shoot</p>\n          <p>Himself to be relieved of the spite.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XII</span>\n          <p>As he was about to push the gun's trigger</p>\n          <p>He sights a thorny rose beside his feet</p>\n          <p>On a pool of blood that made him shiver,</p>\n          <p>He picked it &amp; under a tree, he found a seat.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XIII</span>\n          <p>A seat beside the pile of corpses</p>\n          <p>That were forming a haunting shadow.</p>\n          <p>Grief, misery &amp; sorrow now courses</p>\n          <p>Through his veins that are now hollow.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XIV</span>\n          <p>He had a lot of blood loss from the wound</p>\n          <p>In his arm, yet he hangs onto the rose</p>\n          <p>Firmly, while he also clutches the shroud</p>\n          <p>Of his comrade, who died without a repose.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XV</span>\n          <p>The thorny rose stays with &amp; by him</p>\n          <p>Until he breathes his last breath,</p>\n          <p>He wonders if someone read the poem</p>\n          <p>He wrote near that shore as now he is dead.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XVI</span>\n          <p>He died under the lonely shade of a tree</p>\n          <p>While a wind blows, making the leaves fall</p>\n          <p>On his body, that once was on a kill spree,</p>\n          <p>As nature marks a grave for him, this fall.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XVII</span>\n          <p>The battlefield had become a graveyard</p>\n          <p>Without anyone's name. Corpses lie in wait,</p>\n          <p>While a silent wind blows through the yard,</p>\n          <p>As it's September, a month that they hate.</p>\n        </div>"
  },
  "poems/the-blue-scarf.html": {
    "title": "The Blue Scarf",
    "subtitle": "She worked at a bookshop that played music for wanderers.",
    "form": "Narrative Verse",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>A wry memory alludes my mind</p>\n          <p>As I think about a straining rhyme</p>\n          <p>For a poem that is hard to write</p>\n          <p>While the world changes with time.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>Opposite to the bus stop's street</p>\n          <p>Was a bookshop laden with lily</p>\n          <p>And juniper that formed a sweet</p>\n          <p>Scenery in order with the reality.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>The shade of this old bus stop</p>\n          <p>Misses the serene glimpses of her,</p>\n          <p>Who worked at an artful bookshop</p>\n          <p>Which played music for the wanderer.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>I used to wait for my bus on a floor</p>\n          <p>Until I noticed flowers that wither,</p>\n          <p>Through the window of that store</p>\n          <p>Which are still there, except her.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>She had a pashmina for the winter</p>\n          <p>And a light blue scarf to cover her</p>\n          <p>Hair that would make even summer</p>\n          <p>Shy &amp; wary until it's September.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>Her long hair flowed with the winds</p>\n          <p>That were chilly &amp; cold in October</p>\n          <p>While the enigma of her red heels</p>\n          <p>Made me feel in peace, like a river.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>I met her on a fateful rainy day</p>\n          <p>In this stop's magnanimous shade</p>\n          <p>As her eyes made my thoughts stray</p>\n          <p>While I hid my emotions in charade.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>It seemed as if she could clearly see</p>\n          <p>The wicked world &amp; its foolish ways</p>\n          <p>From eyes that were blue like the sea</p>\n          <p>Yet I write a verse that only fakes.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IX</span>\n          <p>It's been many seasons since I saw</p>\n          <p>Her in that empty book store</p>\n          <p>Which without her, is like a flaw</p>\n          <p>And the music fades with no flow.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">X</span>\n          <p>Therefore all I do is keep her</p>\n          <p>Alive in my melancholic memory,</p>\n          <p>As we met in the shade of a September</p>\n          <p>Who now lives on through my poetry.</p>\n        </div>"
  },
  "poems/a-beautiful-curse.html": {
    "title": "A Beautiful Curse",
    "subtitle": "An oak tree. Unanticipated rain. A love that only blooms in verse.",
    "form": "Narrative Verse",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>A beautiful autumn night sky</p>\n          <p>Enveloped a rather desolating</p>\n          <p>Conversation which seemed shy</p>\n          <p>While a nightingale was in hiding.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>An oak tree on top of a hill</p>\n          <p>Had leaves of colour blue</p>\n          <p>That fell &amp; left a trail in shrill</p>\n          <p>While a chilly &amp; cold wind blew.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>The changes in the seasons</p>\n          <p>Made her nonchalantly smile</p>\n          <p>&amp; they faded swiftly with treasons</p>\n          <p>Of my past, that still hide in a lie.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>A glimmer of lightning fazed</p>\n          <p>Us as we stood in the shade</p>\n          <p>Of an oak tree that was hazed</p>\n          <p>By the autumn's lie in charade.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>Unanticipated rain poured</p>\n          <p>On my already anxious heart</p>\n          <p>And on the tree that ignored</p>\n          <p>This life which has kept us apart.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>I never tended to care about</p>\n          <p>The seasonal changes around me</p>\n          <p>But when I read a poem in doubt</p>\n          <p>My love for her bloomed like a lily.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>Various seasons had passed</p>\n          <p>And in grief we diverged our path</p>\n          <p>While only memories could last</p>\n          <p>As now I sit under a shed of lath.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>This thin shed hasn't provided</p>\n          <p>Shade from the rain as I write</p>\n          <p>About a love that has subsided</p>\n          <p>As I await a nostalgic night.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IX</span>\n          <p>I stumbled upon the old oak tree</p>\n          <p>Whose blue leaves fall in autumn</p>\n          <p>This night sky frees me from misery</p>\n          <p>And a memory seeps in my poetry.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">X</span>\n          <p>Poetry that alludes me everyday</p>\n          <p>Has been about a seasonal woman</p>\n          <p>That dances by a garden where I lay</p>\n          <p>Dreaming under the oak tree, in autumn.</p>\n        </div>"
  },
  "poems/empty-reasons.html": {
    "title": "Empty Reasons",
    "subtitle": "A poem of loss, written on the spot",
    "form": "Rhymed Verse · ABAB",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>Hefty winds blow by my abode</p>\n          <p>Bringing the desolating weather</p>\n          <p>That changes direction of a door</p>\n          <p>That brings me another trice without her.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>Another spring without her mention</p>\n          <p>As I walk into my garden that does wither</p>\n          <p>I reminisce in those warm memories of affection</p>\n          <p>That has left this fallow garden, along with her.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>Another summer approaches, where her eyes</p>\n          <p>Do not throw shade on my heart that is frail,</p>\n          <p>Making me wish that this poem flies</p>\n          <p>To a place where her conscience gets to bail.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>Another rain without the sight of the blue umbrella</p>\n          <p>That protected her from rain as she sauntered</p>\n          <p>Past the gallery, elegantly into a cappella</p>\n          <p>At the theatre without any nerves watered.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>This is to her and always her</p>\n          <p>I am pleased to where to she is heading</p>\n          <p>I wish her the best for the upcoming future,</p>\n          <p>As I continue to never cross paths with her.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>As another spring ends without her mention,</p>\n          <p>I write to commit a poetic treason</p>\n          <p>As she still carelessly without contention</p>\n          <p>Cuts through my frail heart and its reason.</p>\n        </div>"
  },
  "poems/after-many-seasons.html": {
    "title": "After Many Seasons",
    "subtitle": "Reunion and acceptance",
    "form": "Rhymed Verse · ABAB",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>I woke up remembering her face</p>\n          <p>A face that beamed with elegance</p>\n          <p>While life goes on without a trace</p>\n          <p>My soul now, awaits her embrace.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>I caught a glimpse of her strolling on a winter day</p>\n          <p>The cold flowers received her hand's warmth</p>\n          <p>A string of words caught at my diary's bay</p>\n          <p>Hopeless words that are filled with thorns.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>But an old regret came in like it was there</p>\n          <p>Waiting by the shore of my mind</p>\n          <p>A ghost that lingered in the salt air</p>\n          <p>Reminding me that life isn't always kind.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>She sauntered across the garden's bridge</p>\n          <p>As if elegance was personified by her,</p>\n          <p>All I can do is pray that I get a chance</p>\n          <p>To tell her what I couldn't since that cold December.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>Her shadow falls on the fallen leaves</p>\n          <p>And as she passes by the dull daffodil</p>\n          <p>The feelingless garden now grieves</p>\n          <p>While I fail to conjure any syllable.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>Our eyes met again on this fateful day</p>\n          <p>My heart stopped as she turned towards me</p>\n          <p>Her smile is as beautiful as the night we met in a cafe</p>\n          <p>While I just stood there thinking it wasn't to be.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>After many seasons my umbrella found a companion,</p>\n          <p>Prattling about the good ol' days</p>\n          <p>We strolled through the sanctuary</p>\n          <p>And I pondered if eternity could feel this way.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>When we strolled at the end of the place</p>\n          <p>She bid me farewell at the bus stop in the rain</p>\n          <p>Leaving me alone in the garden of words</p>\n          <p>Making me hope that one day we could meet again.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IX</span>\n          <p>She was a woman I once knew</p>\n          <p>Like a jasmine she poises elegantly</p>\n          <p>Even when it rains on days that are blue</p>\n          <p>While I try to move on through the lines of my poetry.</p>\n        </div>"
  },
  "poems/red-sweater.html": {
    "title": "Red Sweater",
    "subtitle": "Written under the shade of a garden",
    "form": "Rhymed Verse · ABAB",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>The sun shines less than usual</p>\n          <p>Like a lost love finding itself in a gravel,</p>\n          <p>The fallen leaves do not appear as lovely</p>\n          <p>An autumn's sign for travel.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>I sit under the shade of this garden</p>\n          <p>Penning my thoughts down that take shape</p>\n          <p>Of poetry that remains too brazen</p>\n          <p>For my heart has lost an escape.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>A sudden gush of wind flows past my book</p>\n          <p>Flowers of the garden dance to its tune</p>\n          <p>While I smoke away my feelings that shook</p>\n          <p>Me and my poetry on a fateful day of June.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>Thoughts become fleeting under this tree</p>\n          <p>Memories that once sparked an ember</p>\n          <p>In my heart still lurks in my poetry</p>\n          <p>Keeping me warm in this lonely winter.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>She often wore a red sweater,</p>\n          <p>Calling me when she wanted attention</p>\n          <p>Texting me to get her man under the weather</p>\n          <p>Making me join my own pitiful convention.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>The birds fly from one place to another</p>\n          <p>Reminding me her words of that night</p>\n          <p>When she cried a river, and now I ponder</p>\n          <p>With all the time that has passed by, will she think of me tonight?</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>My friends tell me to quit smoking</p>\n          <p>But it's these memories that haunt my fingers</p>\n          <p>Which grips the cigarette, burning</p>\n          <p>The sorrows inside my heart that to this day, lingers.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>Like a cigarette that breaks in the rain</p>\n          <p>I break my heart every time I see this deluge</p>\n          <p>It hides my seemingly shallow pain</p>\n          <p>And under this shade my pen takes a silent refuge.</p>\n        </div>"
  },
  "poems/almeres-fair.html": {
    "title": "Almere's Fair",
    "subtitle": "A bookstore by a lake — and loves that pass through, season after season.",
    "form": "Rhymed Verse · ABAB",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>Are you going to the Almere's fair?</p>\n          <p>Where the wind blows beside a field</p>\n          <p>With junipers, that rest by my lair,</p>\n          <p>As I write a poem of sorrow that I yield.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>I open my bookstore every season</p>\n          <p>Here in this crowded fair by a lake</p>\n          <p>Where travellers without any reason</p>\n          <p>Stumble upon books they forsake.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>I reminisce the day I failed</p>\n          <p>To express love in my poem,</p>\n          <p>A love which wasn't conveyed</p>\n          <p>In words, that weren't in tandem.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>My heart remains heavy</p>\n          <p>With regret, sorrow and grief</p>\n          <p>As I walk by this field of Daisy</p>\n          <p>And Alpine that shower relief.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <p><em>Will you be there, my first love?</em></p>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>Eating candy near a willow tree</p>\n          <p>Just like when we were thirteen,</p>\n          <p>Smiling with innocence and glee</p>\n          <p>As I stood there, with a hot caffeine.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <p><em>Will you pass by too, my second love?</em></p>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>Strolling by the lake in a blue dress,</p>\n          <p>In which I saw you for the first time</p>\n          <p>When my mind was in distress,</p>\n          <p>As my heart had felt pain on its dime.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <p><em>Will you saunter through the fair, my nostalgic love?</em></p>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>Would I find those eyes again</p>\n          <p>That I seemed to have forgotten,</p>\n          <p>While my heart braces for pain,</p>\n          <p>As it doubts the flowers that had fallen.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>Even in this fair's crowd, my alone</p>\n          <p>Eyes search for your long hair</p>\n          <p>And your eyes, as your cologne</p>\n          <p>Still lingers in the Spring's air.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <p><em>Will a new love pass through my bookstore?</em></p>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IX</span>\n          <p>Would my heart be paranoid</p>\n          <p>To be vulnerable over a love</p>\n          <p>That may find its place in a void</p>\n          <p>Inside my heart, that awaits a dove.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">X</span>\n          <p>Upon meeting her would I ever</p>\n          <p>Write again, as only the sorrow</p>\n          <p>In my lonely heart helps me lever</p>\n          <p>My hands to write for a tomorrow.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XI</span>\n          <p>Will her eyes tell me a story</p>\n          <p>That is unique, making my heart</p>\n          <p>Light yet undoubtedly heavy</p>\n          <p>Unless this rigid fate plays its part.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XII</span>\n          <p>Its a new season again under</p>\n          <p>This old willow tree's shade,</p>\n          <p>And it rains outside while I cover,</p>\n          <p>The books that just are a facade,</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XIII</span>\n          <p>For the flowers that often bloom</p>\n          <p>Just to dare the omni season,</p>\n          <p>Which is love, that brings doom</p>\n          <p>To the lover's heart, as a treason.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XIV</span>\n          <p>So are you going to the Almere's fair?</p>\n        </div>"
  },
  "poems/the-bar-under-a-lonely-star.html": {
    "title": "The Bar Under a Lonely Star",
    "subtitle": "Only broken people gathered there — just to get a sip of whiskey & lime.",
    "form": "Rhymed Verse · ABAB",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>I stumbled upon a secluded bar</p>\n          <p>One breezy &amp; windy December day.</p>\n          <p>It was situated under a lonely star</p>\n          <p>But, was filled with people anyway.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>Here only broken people gathered</p>\n          <p>Just to get a sip of whiskey &amp; lime</p>\n          <p>That has long since been withered</p>\n          <p>On these long days with no sunshine.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>I entered with no specific objective</p>\n          <p>But this peculiar place was on its own</p>\n          <p>Tied to a premise in an anxious subjective</p>\n          <p>Tone, only to get hopelessly drunk alone.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>A gloomy shadow looms over</p>\n          <p>An old man's scar filled face,</p>\n          <p>A face that hadn't come to lower</p>\n          <p>Its pride which now, seems a charade.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>A semi shattered vinyl player</p>\n          <p>Grinds through the gloomy night</p>\n          <p>And the lonesome could only savour</p>\n          <p>A sharp tonic with a lonesome plight.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>Wistful smiles popped on the buzzed</p>\n          <p>As a specific melody reminded them</p>\n          <p>Of a time when the heart wasn't puzzled,</p>\n          <p>And of a time when life was a poem.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>A trumpet blares through the shade</p>\n          <p>Stirring a melancholic sensation</p>\n          <p>And the piano artfully lets the pain fade</p>\n          <p>While it dissolves in the mind's ocean.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>The sounds of distant glasses clink</p>\n          <p>Carried by a sadness stuck on their face</p>\n          <p>Made my empty and horrid heart sink</p>\n          <p>In misery as a dire mockery was in place.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IX</span>\n          <p>And as I sit down by this lonely lady</p>\n          <p>Whose main motive in life was only to</p>\n          <p>Measure her costly glass of brandy</p>\n          <p>At the bar where the bill stayed due.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">X</span>\n          <p>My gutted face enveloped in sorrow</p>\n          <p>My pale and dry lips subtly drown</p>\n          <p>In the glass of whiskey too shallow</p>\n          <p>While my hands tremble to a sound.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XI</span>\n          <p>A sound of a woman who is beside me,</p>\n          <p>Forcing me to hopelessly remember</p>\n          <p>A time with a woman who was like a maple tree,</p>\n          <p>Who blew away with the winds of December.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XII</span>\n          <p>This woman beside me was dressed in blue,</p>\n          <p>And tried to see the scribbling in my diary</p>\n          <p>But a cold wind came in and hastily blew</p>\n          <p>Away the poems that described a canary.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XIII</span>\n          <p>Before midnight, I exited from this bar</p>\n          <p>Which almost made me its abductee.</p>\n          <p>Now in the night sky, I see a lonely star</p>\n          <p>That others inside the bar couldn't see.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XIV</span>\n          <p>I light up a cigarette as I stand below</p>\n          <p>A streetlight that illuminates the dark</p>\n          <p>Streets of this town covered in snow</p>\n          <p>And the rain while I decide to embark,</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XV</span>\n          <p>On a journey to find the correct word</p>\n          <p>To complete this rigid poem of mine.</p>\n          <p>I smoke while I mark a grave for a bird</p>\n          <p>Which lied inside my lonely &amp; rusty heart.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XVI</span>\n          <p>It died without seeing a ray of sunshine</p>\n          <p>That escapes from my diary, but I can't save</p>\n          <p>These poems in my diary forever, that act as light</p>\n          <p>For the flowers to bloom at my isolated grave.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XVII</span>\n          <p>Time has hurried on, as I kept on writing</p>\n          <p>These miserable poems, that have me and her.</p>\n          <p>&nbsp;</p>\n          <p>While she blew away with the cold winds</p>\n          <p>Of December, that have now, run full circle.</p>\n        </div>"
  },
  "poems/homeward-bound.html": {
    "title": "Homeward Bound",
    "subtitle": "Going back to a city that no one calls home.",
    "form": "Rhymed Verse · ABAB",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>This car won't slow down in dim light</p>\n          <p>Even with the heavy riverside wind</p>\n          <p>Pushing against it with a might</p>\n          <p>Which makes it seem like a headwind.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>The winds blow here ferociously</p>\n          <p>Along these country roads with a sunshine</p>\n          <p>That caresses my heavy heart tenderly</p>\n          <p>Beside these fields of Juniper &amp; Alpine.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>A nostalgic memory races my mind's lair</p>\n          <p>As the highway wind hits my face</p>\n          <p>And brushes through my messy hair</p>\n          <p>While sun shines brightly on my charade.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>I recall the times when fruits were collected</p>\n          <p>From the lakeside farms that were near</p>\n          <p>Our place where everyone gathered</p>\n          <p>And came to the country home I hold dear.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>Grandparents, uncles, aunts, cousins,</p>\n          <p>Every one of them visited to enjoy</p>\n          <p>The cool summer breeze, that now</p>\n          <p>Blows with an empty ahoy</p>\n          <p>As time slipped through &amp; didn't allow,</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>Me to even bid farewell to the people</p>\n          <p>I held in great regard and affection,</p>\n          <p>Now I stand in these fields that has a beetle</p>\n          <p>Climbing on a branch with no conviction.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>The beetle reminded me of myself</p>\n          <p>A kid who's ignorance was bliss</p>\n          <p>Now I see is a world that has scared itself</p>\n          <p>From words that feign love in distress.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>Confabulating with the people around</p>\n          <p>I spent my summer days there in solace</p>\n          <p>Now I am bound to my city with a frown</p>\n          <p>On my face &amp; with boots without shoelace.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IX</span>\n          <p>The old people that once had stayed</p>\n          <p>Already died in a simple twist of fate.</p>\n          <p>So I had visited today, that tragic shade</p>\n          <p>To pay respects in silence while I did wait.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">X</span>\n          <p>With feelings overwhelming to the core</p>\n          <p>I write this poem as I travel to the airport</p>\n          <p>With stuff that I bought from the store</p>\n          <p>Where people smiled to heal scars in rapport.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XI</span>\n          <p>I wish to be homeward bound in reality</p>\n          <p>Except, I am going to a place</p>\n          <p>That I can hardly call a home in fidelity</p>\n          <p>So I write this verse with a mask on my face.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XII</span>\n          <p>The place I go back to with a frown</p>\n          <p>Has no one to even call my own</p>\n          <p>Hypocrites, surround me as I drown</p>\n          <p>In the sea of words that I have never known.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XIII</span>\n          <p>No lover waits for me back in the city</p>\n          <p>The one whom I loved long ago had left</p>\n          <p>And now this place that I leave is empty</p>\n          <p>Except for a blue bird that lies with its nest.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XIV</span>\n          <p>Never could I see the stars in the city</p>\n          <p>Yet to write beneath the diamond sky</p>\n          <p>In that country town in tranquility</p>\n          <p>Is how I would like my nights to go by.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XV</span>\n          <p>The town has flowers glittered</p>\n          <p>That never bend in the rainfall</p>\n          <p>But now the flowers in the city have withered</p>\n          <p>As there hasn't been sunshine since fall.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XVI</span>\n          <p>All these places have their own memories</p>\n          <p>Well it be the city or that town since years,</p>\n          <p>Yet I enjoyed my days in the windy breeze</p>\n          <p>Of my childhood place that I leave in tears.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XVII</span>\n          <p>Though I know I will never lose a love innate</p>\n          <p>For people and things that went before</p>\n          <p>But I know that they will stay in my shade</p>\n          <p>As they are in my poems that I still explore.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XVIII</span>\n          <p>These memories will stay in this poem</p>\n          <p>And I will continue to pretend that</p>\n          <p>These memories will remain in tandem</p>\n          <p>As I know I'll often think about those,</p>\n          <p>&nbsp;</p>\n          <p>Flowers that never bend with the rainfall,</p>\n          <p>&nbsp;</p>\n          <p>And the wind that blows through the countryside.</p>\n        </div>"
  },
  "poems/a-rainy-day-of-july.html": {
    "title": "A Rainy Day of July",
    "subtitle": "Met on a rainy day of July — left on a day of autumn.",
    "form": "Rhymed Verse · ABAB",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>Did I ever wryly abide</p>\n          <p>To her nostalgic smile</p>\n          <p>That still lingers on this fray</p>\n          <p>That I wore on a rainy day.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>I saw a shocking reflection</p>\n          <p>By a puddle's misdirection</p>\n          <p>While I picked the fine rose</p>\n          <p>Laying beside my damp toes.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>It was a rainy day of July</p>\n          <p>When I met a woman so shy,</p>\n          <p>She had an umbrella that was blue</p>\n          <p>And a chilly wind had just blew.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>Beauty personified her eyes</p>\n          <p>That made me conjure lies</p>\n          <p>About myself and the poem</p>\n          <p>That I read &amp; write in tandem.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>My love was like a seagull</p>\n          <p>That crashed in a death fatal,</p>\n          <p>Yet she was the only twilight</p>\n          <p>That kindled the sparks inside.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>I left her on a day of autumn</p>\n          <p>That I may regret often</p>\n          <p>As my love for her was hopeless</p>\n          <p>While she made me breathless.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>Could it be luck or fate</p>\n          <p>To meet her on this lane</p>\n          <p>After many sorrowful seasons</p>\n          <p>That made me commit treasons.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>Treasons are the lines of poetry</p>\n          <p>Which I find along with this diary</p>\n          <p>That has her caged with grace</p>\n          <p>Like a flower in a rainy place.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IX</span>\n          <p>It seems my love for her</p>\n          <p>Still sends the same shiver</p>\n          <p>That makes me want to cry</p>\n          <p>Like it was a rainy day of July.</p>\n        </div>"
  },
  "poems/the-gardner.html": {
    "title": "The Gardner",
    "subtitle": "Seasons passed. She kept coming. He never forgot.",
    "form": "Rhymed Verse · ABAB",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>A Gardner, lonely as he could be</p>\n          <p>Works at a garden in the city</p>\n          <p>Where flowers crave to be free</p>\n          <p>From the despondent calamity.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>A calamity that showers rain</p>\n          <p>Full of sorrow and regret</p>\n          <p>That causes a nostalgic pain</p>\n          <p>That he can never seem to forget.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>He observes the world changing,</p>\n          <p>But his pain that seems sweet</p>\n          <p>Abides, &amp; also does the clinking</p>\n          <p>Of glass windows from the street.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>He often notices the woman</p>\n          <p>Who lives in that old house</p>\n          <p>Where the glass clinks during dawn</p>\n          <p>And its a place without a spouse.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>Time and again she comes by</p>\n          <p>The garden for a flower lily,</p>\n          <p>Blooming in peace and solitary</p>\n          <p>And as sun dawns, she bids goodbye.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>Her eyes looked in the garden</p>\n          <p>For something far ahead in life</p>\n          <p>That made him write a poem</p>\n          <p>About a woman who wasn't a wife.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>In summer time, the woman</p>\n          <p>Would wear dark sunglasses</p>\n          <p>That didn't let any human</p>\n          <p>See her exuberant face.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>Spring season was their favourite</p>\n          <p>As she could see more beauty</p>\n          <p>In the garden while the literate</p>\n          <p>Gardener could do his duty.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IX</span>\n          <p>On a rainy day, she would quietly</p>\n          <p>Stand with a blue umbrella,</p>\n          <p>Beside the flowers in the vicinity</p>\n          <p>While raindrops fell on his viyella.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">X</span>\n          <p>In autumn she would look</p>\n          <p>At the brown leaves that fall</p>\n          <p>While she clenched a book</p>\n          <p>With her hands that seemed small.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XI</span>\n          <p>During winter, she would wear</p>\n          <p>A trench coat that was brown</p>\n          <p>And visit the garden lair</p>\n          <p>&amp; In sorrow, they both would drown.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XII</span>\n          <p>Numerous seasons passed</p>\n          <p>While she kept coming to the garden</p>\n          <p>For the flowers that weren't recast</p>\n          <p>As the man had never forgotten.</p>\n        </div>"
  },
  "poems/the-green-umbrella.html": {
    "title": "The Green Umbrella",
    "subtitle": "She walked away under the umbrella I had given her.",
    "form": "Rhymed Verse · ABAB",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>It's a lonely month of June</p>\n          <p>A windless summer time</p>\n          <p>I write with no rhythm or tune</p>\n          <p>As no rainy days are in sight.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>But this season ushered</p>\n          <p>A sudden rain in delight</p>\n          <p>In the heart that shattered</p>\n          <p>Several seasons ago in plight.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>This night chooses a dream</p>\n          <p>That was serene in my eyes,</p>\n          <p>How could I ever forget that smile</p>\n          <p>That resembled a night without lies.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>I saw her near the old bus stop</p>\n          <p>Searching shelter from the rain,</p>\n          <p>I was beside the dusty shop</p>\n          <p>Soaking in a nostalgic pain.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>I gave her the green umbrella</p>\n          <p>Which she once had gifted me.</p>\n          <p>Now she grips the same Viyella</p>\n          <p>With a face full of glee.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>As she walked beside me</p>\n          <p>The rainswept streets fell silent</p>\n          <p>And the winds played a memory</p>\n          <p>Which made my heart heavy.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>I saw a ring on her finger</p>\n          <p>As she was picking a lily,</p>\n          <p>I felt a sorrow that will linger</p>\n          <p>In my poems of chivalry.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>Her hair reflected the moonlight</p>\n          <p>When she caught the bus in a hurry,</p>\n          <p>We bid an emotionless goodbye</p>\n          <p>While the night became hazy.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IX</span>\n          <p>Now it's the month of July</p>\n          <p>The night chooses a dream</p>\n          <p>Where an old love chose to fly</p>\n          <p>But I kept mine, in a poem.</p>\n        </div>"
  },
  "poems/painting-her.html": {
    "title": "Painting Her",
    "subtitle": "She smiled over a novel while I drew her reflection on a wine bottle.",
    "form": "Rhymed Verse · ABAB",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>A railroad rusted in no mystery</p>\n          <p>Is beside a small coffee house,</p>\n          <p>I try to paint a vivid scenery</p>\n          <p>Dusted by life without a spouse.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>In my quiet longing for the spring</p>\n          <p>I see a woman walk by in the rain</p>\n          <p>While flowers bloom in the morning</p>\n          <p>That were withered for long in pain.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>The winds of the rain dance</p>\n          <p>Around her which reminds me</p>\n          <p>Of a sparkling coast in Barcelona</p>\n          <p>Where the sun is calm as the sea.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>Sipping the coffee while reading</p>\n          <p>An obscure romance novel,</p>\n          <p>She smiles while I keep painting</p>\n          <p>Her reflection I see on a wine bottle.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>Losing track of weather &amp; season</p>\n          <p>I bide my time for a new artistry,</p>\n          <p>To draw her eyes for no reason</p>\n          <p>On my canvas under an oak tree.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>When the evening comes in haste</p>\n          <p>I smoke a cigarette of mint</p>\n          <p>And like the clouds in Autumn</p>\n          <p>She disappears without a hint.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>As the days of snow approached</p>\n          <p>She stopped visiting this place,</p>\n          <p>Making the memories a facade</p>\n          <p>And turning my art into a daze.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>A painting with a lonely memory</p>\n          <p>Is on my canvas as if it was a fantasy.</p>\n          <p>It's an art that awaits a melody</p>\n          <p>Which danced around her beauty.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IX</span>\n          <p>The season of spring nears me</p>\n          <p>And my loneliness is on a spree</p>\n          <p>Of painting her reminiscent imagery</p>\n          <p>That is etched into my heart for eternity.</p>\n        </div>"
  },
  "poems/ive-known-life.html": {
    "title": "I've Known Life",
    "subtitle": "I've known only one thing that flows through everything.",
    "form": "Rhymed Verse · ABAB",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>My blurred and teary sight</p>\n          <p>Watches the leaves of a tree</p>\n          <p>Dance to the tunes of the rain</p>\n          <p>While I write a poem about a bee.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>I watch as the rain drops pour</p>\n          <p>On my desolated shade,</p>\n          <p>I reminisce a time that bore</p>\n          <p>Sorrows in my life's charade.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>As the lush green leaves fall</p>\n          <p>Reminding me the fall of twenty</p>\n          <p>When a love stayed unrequited</p>\n          <p>From a joyful &amp; hopeful reality.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>These chilly and cold winds</p>\n          <p>Write a melancholic story</p>\n          <p>About the grieve stricken fields</p>\n          <p>In the broken hearted diary.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>My watch is soaked in the rain</p>\n          <p>And raindrops fall &amp; slide down</p>\n          <p>The watch while I smoke in vain</p>\n          <p>Wishing if that could ever change.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>My rusty bicycle is just for show</p>\n          <p>It reminds me of my childhood</p>\n          <p>When life was just too slow</p>\n          <p>And time was spent for good.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>Cold winds accompany the rains</p>\n          <p>While people just don't mind</p>\n          <p>How the lonely world feigns</p>\n          <p>A joy which is only found inside.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>A sorrowful night is received</p>\n          <p>As the day ends and the rain</p>\n          <p>Is visible only under the street</p>\n          <p>Lights that show a way again.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IX</span>\n          <p>Now as the lonesome hours</p>\n          <p>And chilly minutes pass by,</p>\n          <p>I have known only one thing</p>\n          <p>That flows through everything,</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">X</span>\n          <p>I've known life.</p>\n        </div>"
  },
  "poems/dusky-window.html": {
    "title": "Dusky Window",
    "subtitle": "Time passed — transparent as the gushing wind, hollow in its wake.",
    "form": "Rhymed Verse · ABAB",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>The time that passed is like a dusky window</p>\n          <p>It seemed transparent like the gushing wind</p>\n          <p>But what has passed remains hollow</p>\n          <p>From the emotions that seldom rescind.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>You can see through the memory</p>\n          <p>But it's the emotion that brings storms</p>\n          <p>And as it all becomes a melancholy</p>\n          <p>The reminiscence slowly deforms.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>Conversing about time that has passed</p>\n          <p>Is an activity for people who are strife</p>\n          <p>Who find time that has amassed</p>\n          <p>In this maze seldom called life.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>As the cigarette leaves my lips</p>\n          <p>I ponder if memories are canned by fate</p>\n          <p>In the store of my subconscious which slips</p>\n          <p>When it returns memories with an expiry date.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>I exhale the smoke while reminiscing a time</p>\n          <p>When she strolled beside me in October</p>\n          <p>Her hair sailed in the air by the wind</p>\n          <p>Blowing away like my time with her.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>I stroll on the forgotten street</p>\n          <p>With worn out houses but new doors</p>\n          <p>Making me wonder if I could meet</p>\n          <p>Her again on these nostalgic crossroads.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>Now it's all a memory to cherish</p>\n          <p>As most of them should be</p>\n          <p>And when this soul does perish</p>\n          <p>I'll choose to vanish with this memory.</p>\n        </div>"
  },
  "poems/before-we-grey.html": {
    "title": "Before We Grey",
    "subtitle": "Four years. Before our hair turns grey.",
    "form": "Rhymed Verse · ABAB",
    "lang": "en",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>At a distance, autumn is green</p>\n          <p>But my heart keeps feeling blue.</p>\n          <p>Although life spent here was routine</p>\n          <p>Yet these memories always seem new.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>Now its the twilight days of school</p>\n          <p>The memories seem surreal</p>\n          <p>All the friends made are still cool</p>\n          <p>And these four years, we did only dream.</p>\n        </div>\n        <div class=\"divider\"><span class=\"divider-symbol\">◆</span></div>\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>Maybe we meet again in an autumn</p>\n          <p>When our hair may have turned grey,</p>\n          <p>And as we tell our stories with optimism</p>\n          <p>I hope these memories don't fade away.</p>\n        </div>"
  },
  "poems/garden-of-words.html": {
    "title": "Garden of Words",
    "subtitle": "A waka exchange, inspired by the film Garden of Words (2013).",
    "form": "Waka",
    "lang": "en",
    "html": "<div class=\"waka-poem\">\n          <div class=\"waka-verse\">\n            <p class=\"waka-speaker\">Original — Kojiki</p>\n            <p>A distant rumble of thunder,</p>\n            <p>clouded skies.</p>\n            <p>Perhaps rain comes again —</p>\n            <p>if so, will you stay with me?</p>\n          </div>\n          <div class=\"waka-verse\">\n            <p class=\"waka-speaker\">Her reply</p>\n            <p>A distant rumble of thunder.</p>\n            <p>Even if rain comes not,</p>\n            <p>I will stay here with you —</p>\n            <p>and if it rains, would you stay too?</p>\n          </div>\n          <div class=\"waka-verse\">\n            <p class=\"waka-speaker\">The poet, to no one in particular</p>\n            <p>Even if it doesn't rain,</p>\n            <p>I'll be here,</p>\n            <p>waiting for you,</p>\n            <p>or someone like you.</p>\n          </div>\n        </div>"
  },
  "poems/saboot.html": {
    "title": "Saboot",
    "subtitle": "Proof. A classical ghazal form.",
    "form": "Ghazal",
    "lang": "hi",
    "html": "<div class=\"ghazal-couplet\">\n          <p>Raat bhar tumhari yaad se ghire <span class=\"qafia\">hi to hai</span></p>\n          <p>Us yaad mein shamm-e-gham jalaya <span class=\"qafia\">hi to hai.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Chala tha zikr bewafai ka inn baharo mein</p>\n          <p>So tumhara khayal aya magar bhulana <span class=\"qafia\">hi to hai.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Tumse baat hue ek zamaana hua magar</p>\n          <p>Us hasi ko ojhal hona abhi baaki <span class=\"qafia\">hi to hai.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Hum par be-dilli ka ilzaam <span class=\"qafia\">hi to hai</span></p>\n          <p>Iqrar hi sahi muhabbat azaab <span class=\"qafia\">hi to hai.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Koi jurm to nahi tumse anjaan-e-ishq karna</p>\n          <p>Tumhara hum pe waqt guzarna aziyat <span class=\"qafia\">hi to hai.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Kitna be-bas karega ab ye teri-meri chuppi</p>\n          <p>Jaan-e-jaan ye ghazal mein tera naam <span class=\"qafia\">hi to hai.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Tera khil jana mujhse baat karke sachai <span class=\"qafia\">hi to hai</span></p>\n          <p>Tera yun baat talna har baat pe haan <span class=\"qafia\">hi to hai.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Ab inn hothon pe naam tera to nahi</p>\n          <p>Fir bhi bahare tera pata dhundte <span class=\"qafia\">hi to hai.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Kitne hi dil-farebi reh jao tum 'Raahi'</p>\n          <p>Ye ghazal saboot hai ki ye pyaar <span class=\"qafia\">hi to hai.</span></p>\n        </div>"
  },
  "poems/dariya.html": {
    "title": "Dariya",
    "subtitle": "The River. A strange affliction called love.",
    "form": "Ghazal",
    "lang": "hi",
    "html": "<div class=\"ghazal-couplet\">\n          <p>Ye dillagi bhi kaisi anokhi bimari hai</p>\n          <p>Itne din beet gaye tab bhi yaad suhani hai.</p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Tez hawa ne mujhse pucha</p>\n          <p>Iss mohabbat se sawaal puche sabne hai.</p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Humse na pucho ye beete hijr ke kisse</p>\n          <p>Har kisse mein unki beparwahi ka zikr hai.</p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Ye cigarette ka dhua le aata hai saath samundar paar</p>\n          <p>Hume kya pata tha ye yaadein bhi beheti hai.</p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Ab kis khushakismat ko tum chaahton se dekhte ho</p>\n          <p>Barbaadi dekh kar bhi hum haat malte hai.</p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Hum ghazal mein tumhara naam nahi zikr hone dete</p>\n          <p>Inn yaad bhare khaton ko rusvan nahi hone dete hai.</p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Ye jaam roz rooh ko pyasi kar deti hai</p>\n          <p>Pyaas hi sahi phir ye udaasi kahan se dhundh laati hai.</p>\n        </div>"
  },
  "poems/hum-kahan-jayenge.html": {
    "title": "Hum Kahan Jayenge",
    "subtitle": "A ghazal of parting",
    "form": "Ghazal",
    "lang": "hi",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>Hai qayanaat-e-mehfil saji humare liye</p>\n          <p>Tum kaha jaoge, hum kaha jayenge.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>Logon ki to aadat hai bichhadna</p>\n          <p>Lapata sab hai par, hum kaha jayenge.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>Raatein kat ti nahi ab pehele jaisi</p>\n          <p>Tere khyaal mein doob kar, hum kaha jayenge.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>Ab wo peheli si guftugu nahi tumhare saath</p>\n          <p>Unn palon ko yaad karke, hum kaha jayenge.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>Koi hasil na tha aarzu ka magar</p>\n          <p>Be-aarzu tumse alag hogaye, hum kaha jayenge.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>Kabhi kabhi yun lagta hai ke tum laut aayega</p>\n          <p>Par ab mile bhi to hum kaha jaayenge.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>Dil se dil milana chahta hoon firse lekin</p>\n          <p>Dil-o-jaan to tumne rakh liya, hum kaha jayenge.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>Ek hi baat hai jo ek baras se kehena chaaha</p>\n          <p>Dil ki baat kehekar bhi, hum kaha jayenge.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IX</span>\n          <p>Tum kyon phirse inhi raston mein mujhe chhod aaye</p>\n          <p>Ab yahaan se wapis hum kaha jayenge.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">X</span>\n          <p>Ab bikharne ko hai ye teri meri daastaan-e-rang-o-bu</p>\n          <p>Tum kaha jaaoge hum kaha jayenge.</p>\n        </div>"
  },
  "poems/kuch-lafz.html": {
    "title": "Kuch Lafz",
    "subtitle": "A ghazal of words that remain",
    "form": "Ghazal",
    "lang": "hi",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>Kuch lafz aaj bhi kisi ke naam reh gaye</p>\n          <p>Din ba din lafz kam safaat zyada beh gaye.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>Yun patjhad tanhai mein guzaarke</p>\n          <p>Hum sardi ka hausla badhaate gaye.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>Aaj gulshan se guzarte hue ek khayal aya</p>\n          <p>Kuch khayal jo raat ko sataake subha chale gaye.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>Tere gham ko jaan ki talaash thi</p>\n          <p>Talaash mein hum gham-o-jaan ho gaye.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>Jab gham ke waje khatm hote rahe</p>\n          <p>Tab tumhari yaadein wapis aake theher se gaye.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>Aisi bhi kya bekhudi hai Raahi</p>\n          <p>Itna bebas fir ek bahaar ke liye ho gaye.</p>\n        </div>"
  },
  "poems/door-jaake-basi.html": {
    "title": "Door Jaake Basi",
    "subtitle": "A ghazal of longing across distance",
    "form": "Ghazal",
    "lang": "hi",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>Tu jab door jaake basi to mere qareeb lagi</p>\n          <p>Khuda hi jaane ye dil ab kya mod lega.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>Rubaru meri dhadkan bhi samajhne lagi</p>\n          <p>Ke tujhse milane ko sama ab kayi muddat lega.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>Ek hi jijhak raha haal-e-dil sudhaarne mein</p>\n          <p>Ke ye fasaana fir kahi tera zikr lega.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>Jo apne dil pe guzari hai wo koi kya jaane</p>\n          <p>Isi umeed mein jeele ke dil tujhe bhula lega.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>Ab kese kisi se marasim badhaye hum</p>\n          <p>Yahi dar hai ke koi marasim tujh tak pahuncha lega.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>Fir koi nayi pur-kashish qareeb aa rahi hai</p>\n          <p>Iski ada gulshan se jaane mein waqt lega.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>Dil-e-nadaan iss halchal ka pata bata</p>\n          <p>Jo ishq dekar mera dard lega.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>Bahaar kata rahe hain chalte chalte</p>\n          <p>Afsos ye gulshan meri yaadein lega.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IX</span>\n          <p>Sahulat se guzar jao meri jaan</p>\n          <p>Ye mohabbat sach mein meri jaan lega.</p>\n        </div>"
  },
  "poems/shayad.html": {
    "title": "Shayad",
    "subtitle": "A ghazal of perhaps",
    "form": "Ghazal",
    "lang": "hi",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>Likhe the khat khwaabon mein bhi tumhe</p>\n          <p>Ek nazm tumhe aur dikhana hai shayad.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>Sher-o-shayari karte rahe sheher sheher</p>\n          <p>Ab bhi yaadein baaki reh gayi shayad.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>Tumhari kitaabe jhaankti hai almaari se</p>\n          <p>Unko na padhne mein hi bhalai hai shayad.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>Ye qalam dhunta hai fir nayi si bedili ko</p>\n          <p>Mujhse ek naya paigam likhwayega shayad.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>Bebasi hai par ankahi chuban si hai,</p>\n          <p>Bade sheher mein ab ghutan si hai shayad.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>Tumhari gali se guzre to aankhe bhar aayi</p>\n          <p>Tumhe bhulaane mein abhi aur waqt lagega shayad.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>Khaas hum bhi the kisi ki nazron mein Raahi,</p>\n          <p>Magar nazar ki khwaishein badalne mein waqt nahi laga shayad.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>Gale lagna ho muhabbat ko to abhi lage</p>\n          <p>Der ho gayi to uske bagair jee lagne lagega shayad.</p>\n        </div>"
  },
  "poems/jaayega-kahan-ab.html": {
    "title": "Jaayega Kahan Ab",
    "subtitle": "A ghazal of the wanderer's question",
    "form": "Ghazal",
    "lang": "hi",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>Ye chand lamho ki baarish bhi ab</p>\n          <p>Kisi aur ke chhat pe baras gayi ab.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>Tumhare jaane anjaane ne kar diya bura haal</p>\n          <p>Tere mere sapne kabhi ek rang na honge ab.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>Jab dukh sukh baantne ke liye sahaara dhundhta fira</p>\n          <p>Par var diga tune bhi meri baat suni nahi ab.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>Jiske liye sher-o-shayari se guftugu fir shuru ki thi</p>\n          <p>Wo hi mere kalam tutne ka wajah bana ab.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>Ye raat ye chandni fir kaha,</p>\n          <p>Raahi tu bhi ruton ka ghulam ban chuka hai ab.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>Har cheez mein jo tu patjhad aur bahaar dhunde firta hai</p>\n          <p>Wahaan kon hai tera, musafir,</p>\n          <p>jayega kahan ab?</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>Waqt ko zaya kar kitne gham-e-shaam bitayega ab?</p>\n          <p>Teri manzil hai yahi, jaayega kahan ab?</p>\n        </div>"
  },
  "poems/hawa-ke-dastaan.html": {
    "title": "Hawa Ke Dastaan",
    "subtitle": "Stories the wind carries home.",
    "form": "Ghazal",
    "lang": "hi",
    "html": "<div class=\"ghazal-couplet\">\n          <p>Ae pichle mausam ke saathi</p>\n          <p>Ab ke baras aas paas bas tanhai <span class=\"qafia\">hai.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Likhta hoon ghazal auron ke liye</p>\n          <p>Mere wo ghazal bhi tumhare naam <span class=\"qafia\">hai.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Yun to apne nazuk se dil ke paas</p>\n          <p>Jaane kis kiske paighaam <span class=\"qafia\">hai.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Koi puche to main kya bataun</p>\n          <p>Mere har khat tumhare naam <span class=\"qafia\">hai.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Thak gaya hun mein iss bhag daud se</p>\n          <p>Par ruk gaya to yaad aata mera intezaar <span class=\"qafia\">hai.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Pankhudi ki tarah bikhar jaati hai zindagi</p>\n          <p>Ye sakht ghadi bhi kitni rukhsaar <span class=\"qafia\">hai.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Gaur se dekhun gulon ke kaanto ko to log haste <span class=\"qafia\">hai</span></p>\n          <p>Zakhmon par gaur karna bhi ab haraam <span class=\"qafia\">hai.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Jinn par apni saari khushiyon ko kiya nisaar</p>\n          <p>Aaj wo hi ehd-e-tanhai ke jimmewaar <span class=\"qafia\">hai.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Usko fursat nahi milti ke wo palat ke dekhe</p>\n          <p>Hum hi bedilli mein doobke berozgaar <span class=\"qafia\">hai.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Kitaab ke beech aaj bhi uski tasveer <span class=\"qafia\">hai</span></p>\n          <p>Aankhein aaj bhi karti dard-e-karobaar <span class=\"qafia\">hai.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Main kyun aisi tanhai se juda hoon.</p>\n          <p>Ye tanhai to ab meri dil-o-jaan <span class=\"qafia\">hai.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Logon ke beech khudko paata hoon</p>\n          <p>Magar dil akela bitata gham-e-shaam <span class=\"qafia\">hai.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Tumse pehele khat jo likhte the</p>\n          <p>Ab wo saare hawa ke dastaan <span class=\"qafia\">hai.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Aur tumhare baad ke jo khat likhta hoon</p>\n          <p>Wo to tumhare khushbu ke nishaan <span class=\"qafia\">hai.</span></p>\n        </div>"
  },
  "poems/udaasi-ka-itiraf.html": {
    "title": "Udaasi Ka Itiraf",
    "subtitle": "A confession the heart makes only to itself.",
    "form": "Ghazal",
    "lang": "hi",
    "html": "<div class=\"ghazal-couplet\">\n          <p>Ye musafir jaam se pehele nazar fere <span class=\"qafia\">nahi</span></p>\n          <p>Hum shaam ko piye bina kahi nikle <span class=\"qafia\">nahi.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Yuhin mausam ki ada dekh ke yaad aya</p>\n          <p>Iss qismat ka kabhi tha saath <span class=\"qafia\">nahi.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Gayab ho jaate hai ye nazmein aangan se har shaam</p>\n          <p>Ab to apne tanhai ka bhi sahaara <span class=\"qafia\">nahi.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Agar muhabbat fir hoti qismat mein likhi</p>\n          <p>To iss bahaar ka hota itna afsos <span class=\"qafia\">nahi.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Gulshan ko kitna bhi paani daalo</p>\n          <p>Inn gulon ke fitrat mein titliyan <span class=\"qafia\">nahi.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Ab bedilli kaha chhodegi mera sahaara</p>\n          <p>Uske liye intezar karna tak to chhoda <span class=\"qafia\">nahi.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Dil chidiyon ki aawaaz parakh leta hai</p>\n          <p>Itne aziyat jhelne ke baad dil ab nadaan <span class=\"qafia\">nahi.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Log taquluff ko bhi samajte hai ikhlas</p>\n          <p>Har koi haath milaane wala dost <span class=\"qafia\">nahi.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Jheel ke bahaav mein beh jaate hai har raat</p>\n          <p>Hum dil se nikale hue log ek jagah tikte <span class=\"qafia\">nahi.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Raat se pehele hote hum jaam ke paas</p>\n          <p>Subha se pehele chhodte hum saath gilaas ka <span class=\"qafia\">nahi.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Agar tum mil bhi jaate to ye afsaana khatm hota <span class=\"qafia\">nahi</span></p>\n          <p>Zindagi mein to naye afsaano ki koi kami <span class=\"qafia\">nahi.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Aisi udaasi ab kaha milti hai Raahi,</p>\n          <p>Ab to maan lo tumhe isse nafrat <span class=\"qafia\">nahi.</span></p>\n        </div>"
  },
  "poems/khaali-gali.html": {
    "title": "Khaali Gali",
    "subtitle": "Empty lanes, empty evenings.",
    "form": "Ghazal",
    "lang": "hi",
    "html": "<div class=\"ghazal-couplet\">\n          <p>Aaj kal mere gali se to koi nahi guzar raha</p>\n          <p>To hum gali gali se guzar rahe hai kisi <span class=\"qafia\">ke liye.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Gul phir khilne ko bechain hai iss bahaar-e-gulshan mein</p>\n          <p>Dil-e-nadaan jald baazi mein kuch nahi hai paane <span class=\"qafia\">ke liye.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Apni khuli zulfe lapetke bethi hai ek husn pari samne</p>\n          <p>Kaise batlaye ke ab kuch nahi iss dil mein dene <span class=\"qafia\">ke liye.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Uske sawalon ka jawaab tha to magar diya nahi</p>\n          <p>Hass aur diye ashk aankhon ke chupane <span class=\"qafia\">ke liye.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Lagta hai ab uske ishq mein naye tajurbe dekhne ko milenge</p>\n          <p>Par aisa to nahi ke ye raste naye mere kalaam <span class=\"qafia\">ke liye.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Apni befikri mein guzar jao meri jaan</p>\n          <p>Humara ek din ka sath jo thehra wo kaafi hai zindagi bhar ki yaadon <span class=\"qafia\">ke liye.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Ek aur ajnabi haseena se guftugu ki arzoo to hai</p>\n          <p>Par beqarari ae dil tujhe na hua waisa sa kisi aur <span class=\"qafia\">ke liye.</span></p>\n        </div>"
  },
  "poems/intezaar.html": {
    "title": "Intezaar",
    "subtitle": "The only thing that stays.",
    "form": "Ghazal",
    "lang": "hi",
    "html": "<div class=\"ghazal-couplet\">\n          <p>Dil mein ab soz-e-intezaar to raha nahi</p>\n          <p>Tumne ye hi baat meri maan li thi <span class=\"qafia\">kya.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Bheegi raatein meri aankhon ki nami chhipa rahi hai</p>\n          <p>Ab aankhon mein tujhe mehfooz rakhna bhi gunnah hai <span class=\"qafia\">kya.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Mere sab ishq-e-alfaaz beasar hi rahe</p>\n          <p>Main koi alag desh jaa chuka hoon <span class=\"qafia\">kya.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Itne haseen chehre hai to mere ird gird</p>\n          <p>Par tum jaisa koi milna mumkin bhi hai <span class=\"qafia\">kya.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Ye patjhad bhi mujhe chain kyon nahi de raha</p>\n          <p>Ek hi shaks tha jahaan mein <span class=\"qafia\">kya.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Ye pal hai jo guzara nahi jaa raha humse</p>\n          <p>Ab humne wo zindagi nahi guzari <span class=\"qafia\">kya.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Kalam to maujud rahega jab koi naya bhi aaye</p>\n          <p>Par tum jaisi koi alqa iss aalam mein hai <span class=\"qafia\">kya.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Naye kaliyon se fir mulaqat karne nikle ke kahi tera roop dikh jaye</p>\n          <p>Par aise haalat bhi humse jaan pehechan rakhte hai <span class=\"qafia\">kya.</span></p>\n        </div>"
  },
  "poems/sardi-ka-mahina.html": {
    "title": "Sardi Ka Mahina",
    "subtitle": "A month that returns with its memories.",
    "form": "Ghazal",
    "lang": "hi",
    "html": "<div class=\"ghazal-couplet\">\n          <p>Sardi mein hi yaadein karti hai wapsi</p>\n          <p>Jo uss rahguzar mein kho gaye the <span class=\"qafia\">shayad.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Aankhon ki mukhbiri ne kuch baatein kahi thi</p>\n          <p>To wo jaan hi gaya hoga hume unse pyar hai <span class=\"qafia\">shayad.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Hazaar baar unse guftugu hui thi lekin</p>\n          <p>Hazaar baar kuch baat reh gayi thi <span class=\"qafia\">shayad.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Lagta nahi ke patjhad ko humse koi gila hai</p>\n          <p>Par patton ki tarah hum to akele reh gaye <span class=\"qafia\">shayad.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Naye gulon se jaan-pehechaan kaha hogi</p>\n          <p>Ae dil, unn zulfon ko tu bhula nahi <span class=\"qafia\">shayad.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Zindagi bhar na bhulunga iss gham ko</p>\n          <p>Anjaam-e-aashiqi ka anjaam hi hai <span class=\"qafia\">shayad.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Hum tauba karke mar gaye the be-maut</p>\n          <p>Tumhare aankhon ki maikashi thi <span class=\"qafia\">shayad.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Jisse bichhda hai ab use bhul jaa Raahi</p>\n          <p>Uske khat uska intezar karte honge <span class=\"qafia\">shayad.</span></p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Aaj fir usi rahguzar par khada hun</p>\n          <p>Jo kuch mausam pehele nakara tha <span class=\"qafia\">shayad.</span></p>\n        </div>"
  },
  "poems/shaam-e-gham.html": {
    "title": "Shaam-e-Gham",
    "subtitle": "Sorrow of the Evening",
    "form": "Nazm",
    "lang": "hi",
    "html": "<div class=\"ghazal-couplet\">\n          <p>Mujhe har waqt yaad aata hai</p>\n          <p>Ke maine tumhe bhula diya.</p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Baarish ke boond sawaal karte hai</p>\n          <p>Jawaab jinke lafzon ne daba diya.</p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Mayusi theher gayi hai dil mein</p>\n          <p>Aisi bekhudi ka sabab hawa mein uda diya.</p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Meri har koshish ishq ki nakaam hi rahi</p>\n          <p>Itna tajurba lekar bhi khud ko hara diya.</p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Meri zillat safar karegi aur kuch door</p>\n          <p>Ek nadi kinare iss khat ka naav bana diya.</p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Tum jao aur dariya dariya pyaas bhujao</p>\n          <p>Ab kisi aur ke dil ko samjhota karao.</p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Hume bhi shauq na tha dastaan sunane ka</p>\n          <p>Taqalluf mein usne to aise hi puch diya.</p>\n        </div>\n\n        <div class=\"ghazal-couplet\">\n          <p>Pyaar se 'Raahi' bulaake taqalluf mein daal diya</p>\n          <p>Ye dil jo toot gaya use naam se bulaake fir jaga diya.</p>\n        </div>"
  },
  "poems/tumhari-yaadein.html": {
    "title": "तुम्हारी यादें",
    "subtitle": "Memories of You",
    "form": "Nazm",
    "lang": "hi",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p class=\"hindi-text\">यूँ मन की गहराई में लिखता हूँ</p>\n          <p class=\"hindi-text\">बातें जो बसा लेती हैं, तुम्हारी यादें</p>\n          <p class=\"hindi-text\">तुम्हारी खुशी, तुम्हारी हँसी</p>\n          <p class=\"hindi-text\">देख फिर लिखता हूँ मन की बातें, तुम्हारी यादें।</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p class=\"hindi-text\">वसंत जाते जाते</p>\n          <p class=\"hindi-text\">नया ऋतु दे गया</p>\n          <p class=\"hindi-text\">अब शरद ने भी पत्तों का सहारा लिया</p>\n          <p class=\"hindi-text\">और लिपट गई आज, तुम्हारी यादें।</p>\n          <p class=\"hindi-text\">लिपट गई आज, तुम्हारी यादें।</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p class=\"hindi-text\">आँखों से संकेत कर</p>\n          <p class=\"hindi-text\">बस जाती थी वो, फूलों की किताबों में</p>\n          <p class=\"hindi-text\">वाक्यों से जो न बोला जाए</p>\n          <p class=\"hindi-text\">वो छंद से समा जाए, वही है तुम्हारी यादें।</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p class=\"hindi-text\">किसी पीपल के पेड़ के नीचे बैठकर</p>\n          <p class=\"hindi-text\">गहरी सोच में उलझती है तुम्हारी यादें</p>\n          <p class=\"hindi-text\">किसी बगीचे से गुज़रते देखूँ सूरजमुखी को</p>\n          <p class=\"hindi-text\">फिर उस गाँव के प्रेम को उभार लाती हैं, तुम्हारी यादें।</p>\n        </div>"
  },
  "poems/pehele-aur-fir.html": {
    "title": "Pehele Aur Fir",
    "subtitle": "First one thing, then another",
    "form": "Nazm",
    "lang": "hi",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>Unki hasi jo bahaaron ke phool sajade</p>\n          <p>Mujhe pehele aashiqi, fir maayusi, aur fir tanhai mein dhakel gaye.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>Chup chupke unhe dekhaa karte the,</p>\n          <p>Dekhte dekhte pehele dilkash, fir aashiq aur fir shayar ban gaye.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>Aap to nazdeek se bhi kitne jhut bolte rahe</p>\n          <p>Pehele ek baar, fir do baar, fir kayi baar dil tod gaye.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>Din ba din badhti gayi, iss zindagi ke zulm hum pe</p>\n          <p>Pehele gulshan, fir gul-badan, fir gul murjhake jhad gaye.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>Haule haule unke saare taqaluff mit gaye</p>\n          <p>Aap se, phir tum hue, fir tum ke baad tum kaun ho gaye.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>Aisa tha kya unke andaaz mein</p>\n          <p>Jo pehele, mann mein, fir soch mein aur fir panno mein sama gaye.</p>\n        </div>"
  },
  "poems/shaam-samay.html": {
    "title": "Shaam Samay",
    "subtitle": "A glimpse of the moon",
    "form": "Nazm",
    "lang": "hi",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>Shaam samay, door kisi suraj mukhi ke bageeche mein</p>\n          <p>Chand ko utarte dekha humne,</p>\n          <p>Chhand bhi kesa? Pura chand.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>Aankhon mein bhi, chitwan mein bhi, chand hi chand jhalakta hai</p>\n          <p>Chaand hi bindi, chaand hi jhoomar, chehara chaand aur hasi bhi chaand.</p>\n        </div>"
  },
  "poems/aangan-ke-phool.html": {
    "title": "Aangan Ke Phool",
    "subtitle": "When the courtyard starts to bloom again.",
    "form": "Nazm",
    "lang": "hi",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>Aangan ke taraf aankh bhatakti reheti hai</p>\n          <p>Lagta hai ek yaad si aakar bethi hai.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>Patjhad ke girte patte udaas lagte hai</p>\n          <p>Jaane girne se pehele hi baat keh dete hai.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>Tanhai ke ghadi mein kisi ka saath nahi</p>\n          <p>Jinn phoolon ko itna sajaya wo bhi murjhaye hai.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>Paani chaaro taraf daalne ke baad bhi</p>\n          <p>Bageeche mein ek hi phool dikhai deta hai.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>Naye phoolon ke beej lag jaye bhi to</p>\n          <p>Vo puraane phoolon ki yaad hi karaate hai.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>Roz aziyat mein doobe raston pe bhatakte hai</p>\n          <p>Ab patjhad se kitni hi ummeed kar sakte hai.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>Himmat nahi haari hai naye dinon ki khalvat mein</p>\n          <p>Bahaar ke phool kabhi to baraste hai.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>Phir bhatakti hai meri aankhe aangan mein</p>\n          <p>Lagta hai koi naya aane ko hai.</p>\n        </div>"
  },
  "poems/naya-rang.html": {
    "title": "Naya Rang",
    "subtitle": "A new colour fills the heart's shadow.",
    "form": "Nazm",
    "lang": "hi",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>Aaj koi nayi kala dekhne ko mili hai</p>\n          <p>Kese kahe unki taraf aankhe bhatakne ko lagi hai.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>Unki justuju mein doob jaane ko mann hai</p>\n          <p>Ye bandagi koi nayi to nahi hai.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>Junoon mein aise khone ka shauq kabhi tha nahi</p>\n          <p>Fir aaj kyon unke husn ka junoon mujhpe sawaar hai.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>Unki chandni baahein jo sama rang de</p>\n          <p>Ab mere dil ke saaye mein bhi rang bhar raha hai.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>Meri aankhe unko takte takte nahi thaki</p>\n          <p>Kher aankhe to sirf dil ka kehna maan rahi hai.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>Unki ada mere pannon mein sama jaaye</p>\n          <p>Iss muddat ki ye hi khwaish hai.</p>\n        </div>"
  },
  "poems/anjaan-sheher.html": {
    "title": "Anjaan Sheher",
    "subtitle": "Life in an unknown city.",
    "form": "Nazm",
    "lang": "hi",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>Jaane kesi bandagi hai mujhe dastaan</p>\n          <p>Ek pal ki khushi ne umr bhar ke ghaav diye.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>Jis se bedilli karne ki koshish ki</p>\n          <p>Usne dua mein mujhe khoye hue armaan diye.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>Kya hi bataye haal puchne walon ko</p>\n          <p>Roz baagh mein gulab ki pankhudi tod diye.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>Ab kaise gair ko apne jazbaat ada kare</p>\n          <p>Uss din ek baar batake gunnah to kar diye.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>Teri galiyon mein hoke hum badnaam</p>\n          <p>Kitne shehron mein apne nek naam kar diye.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>Wo jo taameer hone wali thi bahaaron mein</p>\n          <p>Wo imarat ab barsaat mein khaali kar diye.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>Ye dil ishq ke intezaar mein khala raha</p>\n          <p>So guftugu ki talaash mein dil fir khalvat kar diye.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>Zindagi iss anjaan sheher mein ab kese basar hogi</p>\n          <p>Hum to hurbat ke bagair hosh kho diye.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IX</span>\n          <p>Nahi hai ab kisi aur ke liye soz-e-intezaar</p>\n          <p>Chhoti si zindagi ab tanhai mein guzaar diye.</p>\n        </div>"
  },
  "poems/jaan-e-baharan.html": {
    "title": "Jaan-e-Baharan",
    "subtitle": "The spring that was.",
    "form": "Nazm",
    "lang": "hi",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>Ek jaan-e-baharaan jaan humari thi</p>\n          <p>Kayi mausam pehlee ki baat thi, ab to koi baat hi nahi.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>Wo jo hava ke jhaunke si guzar gayi</p>\n          <p>Unko to humari ab koi bhi khabar nahi.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>Uske khayalon ke bina koi aur soch nahi thi</p>\n          <p>Soch to wahi rahi par wo paas nahi.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>Har pal khilte phulon ki janib to kar mat</p>\n          <p>Haal ab unn phulon ko bhi dekh ke theek nahi.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>Aaj naye mausamo ke liye beqarar to hai</p>\n          <p>Par wo purani barsaat ke siva aangan mein kuch nahi.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>Ab to jaan nisaar kisi aur ke liye kaha hi hoga Raahi,</p>\n          <p>Waisa sa behaal hona to kisi aur ke liye nahi.</p>\n        </div>"
  },
  "poems/ghaav-ki-khushboo.html": {
    "title": "Ghaav Ki Khushboo",
    "subtitle": "Even wounds carry a fragrance.",
    "form": "Nazm",
    "lang": "hi",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>Jab tere yaad ke ghaav bharne lagte hai</p>\n          <p>Ek yaad ki khushboo fir mehsoos karne hoon.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>Baagh mein jab gulab ko titaliyan satati hai</p>\n          <p>Tab bahaane mein tumhe yaad karne lagta hoon.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>Kesa sannata chhaya hai iss ghar mein ya Rab</p>\n          <p>Har shaam sirf pal-e-tanhai ka hi tajurba kare ja raha hoon.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>Kitabon ke beech jab jab apne ko khone laga</p>\n          <p>Tab tab zehen se fisli tazkaron ko inn panno mein pata hoon.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>Kyon sukoon ke pal ab sabab mangte hai</p>\n          <p>Aisi madhoshi hai ke nazm ab sukoon ke liye likhta hoon.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>Ab kon hi fark kare sukh ya dukh mein</p>\n          <p>Madari reheke lamho mein bikhar gaya hoon.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>Ab baagh mein phul to saare jhad gaye</p>\n          <p>Chalo, murjhaye phulon se pehechan phir kar leta hoon.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>Phool wapis khilne ka anjaam kabhi to denge iss baagh ko</p>\n          <p>Main to bas anjaam ke intezaar mein lamhe kata raha hoon.</p>\n        </div>"
  },
  "poems/bekashi-ka-saya.html": {
    "title": "Bekashi Ka Saya",
    "subtitle": "The shadow that homesickness casts.",
    "form": "Nazm",
    "lang": "hi",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>Aaj kal sheher mein apne gaon ki yaad mein khoya sa rehta hoon</p>\n          <p>Lagta hai mere panno ko teri ada-e-bekashi phir chha gayi.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>Maine ek umr se apni kitaab mein sambhali hui hai</p>\n          <p>Wahi tasveer jo ek pal bhi nahi dekhi gayi.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>Gulshan murjha raha hai teri haseen ghataon ke bagair</p>\n          <p>So ab bhi mere dil mein teri yaadein kyo nahi murjha gayi.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>Mere naseeb mein ek phool khilne ko laga sada ki mehrumi</p>\n          <p>Par aakhir mein na itminan hua na hi tujhe pyaar.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>Main jaan-e-bahaara tujhe bhulake khush hona chahta hoon</p>\n          <p>Par ye kambaqt yadaash dil ke liye khanjar bankar reh gayi.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>Mujhe koi acha bhi nahi lagta humnaam tera</p>\n          <p>Ab koi tujsa nahi mila tha to pyaar se ummed chali gayi.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>Par inn dino phir mausam beimaan sa lagne laga hai</p>\n          <p>Aisa afasana hai ke panno mein kisi naye ki ada-e-aafat si chha gayi.</p>\n        </div>"
  },
  "poems/aadat.html": {
    "title": "Aadat",
    "subtitle": "What the heart grows used to.",
    "form": "Nazm",
    "lang": "hi",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>Aaj kal unse milkar baat karke</p>\n          <p>Hume yu hi dil behelane ki <span class=\"qafia\">aadat hai.</span></p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>Hawaon mein leherate hue bahaar ko</p>\n          <p>Humse guftugu karne ki <span class=\"qafia\">aadat hai.</span></p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>Baarish ka mausam aaye to kher</p>\n          <p>Hume chhata bhoolne ki <span class=\"qafia\">aadat hai.</span></p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>Patjhad ke mausam ki tanhai ko</p>\n          <p>Humse shayari likhwane ki <span class=\"qafia\">aadat hai.</span></p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>Afsaano mein unse door hokar</p>\n          <p>Hume purane khayalon ko anjaam dene ki <span class=\"qafia\">aadat hai.</span></p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>Ab majboori mein unhe bina mude</p>\n          <p>Humse door jaate dekhne ki bhi <span class=\"qafia\">aadat hai.</span></p>\n        </div>"
  },
  "poems/khawab-ki-dakhili.html": {
    "title": "Khawab Ki Dakhili",
    "subtitle": "When a dream walks in uninvited.",
    "form": "Nazm",
    "lang": "hi",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>Kayi Raatein Guzar Gaye,</p>\n          <p>Uss bewaqt khwab ko dekhe</p>\n          <p>Hue, jisne mujhe mausamo</p>\n          <p>Mein badlav dikhana chhod diya.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>Wo Raat, ittar ki khushboo</p>\n          <p>Jaisi ladki mere khwaab</p>\n          <p>Mein ayi aur mere zaalim</p>\n          <p>Naseeb ki dastaan bangayi.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>Neele aur khule ambar</p>\n          <p>Ke neeche, aur baharon</p>\n          <p>Ki hawaon ki maujudigi</p>\n          <p>Mein, meine tumko paya.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>Neele jharne ki tarah, tum</p>\n          <p>Bhi mere uss khwaab mein,</p>\n          <p>Neeli saari pehenke mere</p>\n          <p>Dil ki takdeere mitane ayi thi.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>Sadak pe tumhare saath</p>\n          <p>Chalte hue na waqt ka</p>\n          <p>Andaaza hua na lihaaz hua,</p>\n          <p>Bas tumhari hasi ka nasha hua.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>Tumhare baalo ki lehero mein</p>\n          <p>Ghum hone ki saajish karte</p>\n          <p>Fir raha tha. Par tumhari aankho</p>\n          <p>Ne saajish ka mauka hi nahi diya.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>Ye khwab tut gaya jab</p>\n          <p>Subah, baarish ki bundo</p>\n          <p>Ne mere khidki se, meri shayri</p>\n          <p>Ke panno mein dakhili paya.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>Ab kayi mausam beet gaye,</p>\n          <p>Ab kayi panchiyo se ishq</p>\n          <p>Karne ki koshish ki, par</p>\n          <p>Tum jaisi panchi nahi mili.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IX</span>\n          <p>Na ab khwabo mein kahi</p>\n          <p>Dikhti ho na kisi kitabcha</p>\n          <p>Ke kone mein, aur na hi</p>\n          <p>Kisi akhbaar ke panno mein.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">X</span>\n          <p>Bas mere zindagi mein kahi</p>\n          <p>Bhi maujood ho, to meri nazm</p>\n          <p>Mein, aur mere shayrion mein</p>\n          <p>Jo ik kali ki intezaar mein hai.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XI</span>\n          <p>Ab firse ye zindagi bahar</p>\n          <p>Leke aya hai, phool gulte</p>\n          <p>Hai to bas unmein tumhari</p>\n          <p>Hassi aur chhavi dikhti hai.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XII</span>\n          <p>Ab mein iss patjhad ke mausam</p>\n          <p>Mein, inn pedo ke neeche, meri</p>\n          <p>Udaasi ko kalam mein, aur uski</p>\n          <p>Khayalo ko syaahi bana betha hun.</p>\n        </div>"
  },
  "poems/patjhad-ka-parichay.html": {
    "title": "Patjhad Ka Parichay",
    "subtitle": "How autumn introduces itself.",
    "form": "Nazm",
    "lang": "hi",
    "html": "<div class=\"stanza\">\n          <span class=\"stanza-num\">I</span>\n          <p>Aaj ye thandi hawa apna</p>\n          <p>Parichaya karta hai mujhse</p>\n          <p>Aur mere kalam se jo dikhata hai</p>\n          <p>Khwab mere dil ko iss suhani raat.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">II</span>\n          <p>Chaudavi ka chandh iss sanjh</p>\n          <p>Rachta hai har shayar ke liye</p>\n          <p>Aisi saajish jo karde shahad</p>\n          <p>Ki mukhi ko bhi sharminda.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">III</span>\n          <p>Beheka bahar hi jaanta hai jo</p>\n          <p>Mujhe mila gaya tha ik shayar</p>\n          <p>Ke khwab se jisne mere</p>\n          <p>Mohabbat ki dastaan palat di.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IV</span>\n          <p>Taras gaye hai meri aankhein</p>\n          <p>Ab uss haseena ko dekhne mein</p>\n          <p>Jo mere khwab mein aakar meri</p>\n          <p>Nazm mein shaamil ho gayi.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">V</span>\n          <p>Ab manzil reh gaye hai anjaan</p>\n          <p>Jo kuch mausam pehle the</p>\n          <p>Jankaar, aur awaara reh gaya</p>\n          <p>Hai ye dil, jo tha pehele samajhdar.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VI</span>\n          <p>Kagazo mein uski taareef</p>\n          <p>Barkaraar hai aur iss chandni</p>\n          <p>Raat ko wo leti hai tashrif</p>\n          <p>Mere dil ki suhaani kavita mein.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VII</span>\n          <p>Mile the hum ik chhote mod pe</p>\n          <p>Jo tha khila bahaar ke phoolo</p>\n          <p>Se, par ab wo sadak mein sirf</p>\n          <p>Reh gaye, murjhaye hue phool.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">VIII</span>\n          <p>Dil jalati thi wo mera, apni</p>\n          <p>Yaari sabke liye dikhake</p>\n          <p>Mein haath malte reh gaya</p>\n          <p>Aur shaamein dhalte gaye.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">IX</span>\n          <p>Ik baar phirse ban gaye</p>\n          <p>Hum dono ishq mein ajnabi</p>\n          <p>Jab pata chala mujhe ki uski</p>\n          <p>Kashmo kashm mein tha anjaana.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">X</span>\n          <p>Lakh haseen dekhe the</p>\n          <p>Par ussa nahi dekha tha</p>\n          <p>Ab bas hai wo shayar ka khwab</p>\n          <p>Aur ek kavi ki bahar-e-mehboob.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XI</span>\n          <p>Iss raat pedo ki shaakho pe aisi</p>\n          <p>Khamoshi chhayi jo use yaad</p>\n          <p>Karne mein karta hai majboor</p>\n          <p>Aur uski yaadein na hoti riha.</p>\n        </div>\n\n        <div class=\"divider\">\n          <span class=\"divider-symbol\">◆</span>\n        </div>\n\n        <div class=\"stanza\">\n          <span class=\"stanza-num\">XII</span>\n          <p>Kuch palo ka hai ye guztaakh sama</p>\n          <p>Kabhi ho payegi wo mujhse juda?</p>\n          <p>Bas lotkar na aye kaafile bahar ke</p>\n          <p>Chalo firse banaya ajnabi zindagi ne.</p>\n        </div>"
  },
  "poems/jhuti-tasalli.html": {
    "title": "Jhuti Tasalli",
    "subtitle": "The lies a poet tells himself.",
    "form": "Nathar Nazm",
    "lang": "hi",
    "html": "<div class=\"stanza nathar-nazm\">\n          <p>Apne mann ki awaaz ko geet samajh, gaano mein uski yaadein dhundta fir, apne dil ki guzaarish ko suljhata firta hoon.</p>\n          <p>Apne aap ko shayar samajh, shayari suna suna kar, apne rooh ko jhuti tasalli de raha hoon.</p>\n          <p>Apne aap ko kavi samajh, uski aankhon ke saaya ko shabdo mein baya karne ki koshish hi karta reh gaya hun.</p>\n          <p>Apne aap ko aashiq samajh, kayi ankahi dastayein banane ki saazish kar betha hoon.</p>\n          <p>Iss sharab aur ye qalam se inn kagazon mein usko amar karne ka jurm apne bhooj pe lekhe bhatakte fir raha hoon.</p>\n        </div>"
  }
};
